'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["pt"]={"g-flurpruefung":["O que está incluído numa inspeção visual e funcional antes de iniciar o trabalho?","Antes da primeira missão do dia.","Verifique apenas o nível de combustível e a cor do veículo.","Verifique os freios, direção, garfos, pneus e dispositivos de segurança de acordo com as instruções de operação.","Faça um test drive com a carga elevada.","A inspeção diária inclui peças e funções relevantes para a segurança de acordo com as instruções de operação."],"g-rueckhalt":["Como você lida com o sistema de retenção do motorista existente?","A empilhadeira possui sistema de retenção obrigatório.","Use-o corretamente enquanto dirige.","Use apenas em pisos irregulares.","Desative-o para viagens curtas.","Os sistemas de retenção pretendidos devem ser utilizados de acordo com as instruções do fabricante; eles fornecem proteção especial em caso de tombamento."],"g-mangelmelden":["O que se aplica a uma empilhadeira com garfo danificado?","Ao verificar, você percebe um dente claramente torto.","Se possível, distribua a carga para o outro dente.","Conduza apenas cargas leves até o próximo serviço.","Não utilize a empilhadeira e comunique o defeito ao responsável.","Equipamentos de movimentação de carga danificados podem falhar; Defeitos relacionados à segurança exigem desligamento até esclarecimento."],"g-einweisung":["Você muda para uma empilhadeira com controles diferentes. O que é necessário antes de usar?","A operação difere do seu veículo anterior.","Instruções relacionadas ao dispositivo e conformidade com as instruções de operação.","Uma breve explicação de um colega não envolvido é sempre suficiente.","Nenhuma informação adicional se você tiver uma licença de empilhadeira.","Uma qualificação geral não substitui as instruções necessárias sobre o dispositivo realmente utilizado."],"g-anbaugeraet":["Você deve usar um anexo. O que você verifica primeiro?","Um novo equipamento muda a forma como a carga é recolhida.","Se o acessório se enquadra na homologação do veículo e na carga permitida.","Somente se o dispositivo pode ser conectado visualmente.","Se o anexo pode ser instalado sem documentação.","Os acessórios podem alterar a capacidade de carga restante e o centro de carga; As aprovações e informações de capacidade de carga devem ser verificadas."],"g-diagramm":["Por que você precisa do diagrama de capacidade de carga?","Uma carga pesada está presente com o centro de gravidade voltado para fora.","Para determinar o caminho mais curto.","Para avaliar a carga máxima permitida dependendo da altura de elevação e do centro de carga.","Para determinar a capacidade do tanque.","As cargas permitidas dependem, entre outras coisas, da distância do centro da carga e da altura de elevação."],"g-lastschwerpunkt":["O que normalmente acontece quando o centro de gravidade se move mais para frente?","Uma longa carga se projeta bem na frente dos garfos.","A capacidade de carga permitida pode diminuir.","A capacidade de carga está sempre aumentando.","A distância não tem influência no momento de tombamento.","Uma distância maior do centro de carga aumenta o momento de tombamento e pode reduzir a capacidade de carga permitida."],"g-gabelabstand":["Como os garfos devem escolher um palete adequado?","Você deseja pegar um palete carregado uniformemente.","Com os dentes o mais próximos possível e apenas num canto.","Com uma distância tão grande que a palete tomba para o lado.","Com espaçamento adequado entre os dentes e material rodante e área de suporte suficientes.","A carga deve ser apoiada de forma segura e tão uniforme quanto possível nos garfos."],"g-schieflast":["Uma carga está empilhada de forma instável. O que é certo?","As caixas de papelão podem cair quando levantadas.","Comece devagar; a carga se estabiliza.","Antes de levantar a carga, fixe-a suficientemente ou remonte-a.","Eleve a carga acima da altura da cabeça para que não atrapalhe.","Cargas soltas ou instáveis ​​podem cair e colocar pessoas em perigo; execute primeiro as medidas de segurança."],"g-personen":["Uma pessoa pode ser levantada em garfos comuns?","Um colega quer alcançar uma luz.","Sim, se o colega usar capacete.","Não, apenas instalações designadas e permitidas podem ser utilizadas por pessoas de acordo com requisitos especiais.","Sim, se apenas uma pequena altura for aproximada.","Os garfos normais não são uma plataforma de trabalho pessoal; O transporte e a elevação de pessoas estão sujeitos a requisitos especiais."],"g-transporthoehe":["Como você costuma transportar um palete?","A estrada está limpa e nivelada.","Com a carga elevada apenas até onde for necessário e de acordo com as instruções de operação.","Com a carga levantada o mais alto possível para melhor visualização.","Com o mastro de elevação fortemente inclinado para a frente, independentemente da carga.","Uma posição de transporte baixa reduz o risco de tombamento e colisões; As instruções do dispositivo são decisivas."],"g-kurvenfahrt":["Por que fazer curvas rapidamente com uma empilhadeira é perigoso?","Você deseja sair rapidamente de um caminho estreito.","Porque apenas descarrega a bateria mais rápido.","Porque a empilhadeira dirige melhor automaticamente.","Porque as forças laterais afetam a estabilidade e podem causar tombamento.","Nas curvas, forças adicionais entram em jogo; a velocidade deve ser ajustada à carga e às condições."],"g-ladebruecke":["O que você verifica antes de entrar em uma ponte de carga?","Você deveria dirigir um caminhão.","Apenas se o caminho parece largo o suficiente.","Capacidade de carga, suporte seguro e proteção contra deslocamento, bem como segurança do veículo.","Apenas se a iluminação está acesa.","As pontes de carga e os veículos devem ser protegidos contra movimento e adequados à carga."],"g-fussgaenger":["Como você se comporta em um cruzamento confuso com pedestres?","As conexões visuais são restritas.","Dirija a uma velocidade adequada, pare se necessário e garanta uma visibilidade segura.","Sempre reivindique o direito de passagem ao transportar uma carga.","Apenas buzine e continue dirigindo.","Os peões têm necessidades especiais de protecção; A velocidade, a visibilidade e a comunicação devem ser adaptadas à rota do tráfego."],"g-batterieladen":["A que você deve prestar atenção especial ao carregar uma bateria de acionamento?","Uma estação de carregamento de bateria é usada.","O local de carregamento pode ser selecionado independentemente das instruções do fabricante.","Chamas abertas são permitidas enquanto o caminhão estiver parado.","Área de carga adequada, ventilação suficiente e especificações do fabricante, bem como proteção contra incêndio e explosão.","Durante o carregamento, podem surgir perigos provenientes de energia elétrica, gases e produtos químicos; as medidas de proteção fornecidas devem ser respeitadas."],"h-beauftragt":["Em que condições é permitido operar uma plataforma aérea de trabalho de forma independente?","Você deve usar uma plataforma de trabalho na empresa.","Se você tiver carteira de motorista.","Se você for adequado, instruído ou qualificado e contratado pelo empregador.","Se você já viu uma plataforma de trabalho.","O empregador deve garantir a idoneidade, qualificações e atribuições de acordo com os requisitos operacionais."],"h-vorpruefung":["O que deve ser verificado antes de iniciar o trabalho com a plataforma aérea?","O palco ficou do lado de fora durante a noite.","Teste visual e funcional de acordo com instruções do fabricante incluindo dispositivos de segurança.","Apenas a cor e a idade do palco.","Se o material de trabalho já está na plataforma.","Antes da utilização, a máquina, os comandos, as funções de emergência e os danos visíveis devem ser verificados de acordo com as instruções de operação."],"h-tragfaehigkeit":["Que informações determinam a carga permitida na cesta de trabalho?","Duas pessoas gostariam de levar consigo ferramentas adicionais.","As pessoas são livres para estimar o peso total permitido.","Só conta o peso da pessoa mais pesada.","A especificação de capacidade de carga para pessoas, ferramentas e materiais não deve ser excedida.","A carga nominal refere-se à carga total permitida, incluindo qualquer material transportado."],"h-untergrund":["O que você considera antes de montar um palco com suportes?","Você está trabalhando perto de uma área ocupada.","Somente ao alcance da lança.","Verifique a capacidade de carga e a regularidade da subsuperfície, bem como o suporte adequado de acordo com as instruções.","No menor número possível de suportes estendidos.","Solo insuficiente ou suporte inadequado podem levar à perda de estabilidade."],"h-wind":["O vento forte se instala. Como você faz isso?","Você se depara com um palco ao ar livre.","Observe os limites do fabricante e caso sejam ultrapassados, interrompa o funcionamento ou baixe o cesto com segurança.","Estenda a plataforma o máximo possível para que fique mais estável.","Reaja apenas se objetos soltos caírem.","As condições de vento permitidas pelo fabricante são limites operacionais; O vento pode criar forças adicionais perigosas."],"h-strom":["Você tem que trabalhar perto de uma linha de energia aérea. O que é crucial?","Uma linha viva está na área de trabalho.","Um capacete substitui a manutenção de uma distância segura.","Basta isolar a cesta e trabalhar sem coordenação.","Esclareça a área de perigo e garanta as distâncias de proteção necessárias ou outras medidas adequadas.","A descarga elétrica também é possível sem contato direto; As medidas de proteção necessárias devem ser determinadas antes do início da operação."],"h-notablass":["Por que o procedimento de descida de emergência precisa ser conhecido?","É possível uma falha no controle normal.","Para que em caso de mau funcionamento seja possível um resgate seguro de acordo com o dispositivo.","Para que o dispositivo funcione mais rápido em operação normal.","Para substituir testes regulares.","Os controles de emergência, a descida de emergência e os conceitos de resgate devem ser conhecidos e funcionais antes do uso."],"h-gelaender":["Como você consegue altura adicional na cesta de trabalho?","Um ponto de montagem está fora do seu alcance.","Suba na cerca da cesta.","Coloque uma tábua no corrimão.","Utilize uma plataforma adequada com altura de trabalho suficiente; não suba nas grades.","Subir na cerca ou em elevações improvisadas coloca em risco a proteção contra quedas."],"h-psaga":["Que requisitos se aplicam aos equipamentos pessoais de proteção contra quedas?","Você usa uma plataforma de trabalho para a qual é fornecido um sistema de retenção.","Qualquer ponto de ancoragem fora do cesto é sempre suficiente.","Observe a avaliação de risco, as informações do fabricante e os pontos de ancoragem adequados.","Não use nenhuma segurança se a cesta tiver grade.","Se e qual EPI é necessário é determinado pela avaliação de risco, fase de construção e instruções de operação."],"h-verfahren":["O palco pode ser movido com a plataforma elevada?","O local de trabalho fica a poucos metros de distância.","Somente se o modelo e as condições de operação permitirem de acordo com as instruções do fabricante.","Sempre, desde que todos aguentem.","Não, nunca, independentemente do projeto e da aprovação do fabricante.","O movimento na posição elevada depende do dispositivo e só é permitido dentro das condições operacionais aprovadas."],"h-kollision":["O que precisa ser organizado ao trabalhar próximo a guindastes ou outras máquinas?","As peças móveis podem atingir o cesto de trabalho.","Nada; a cesta de trabalho está sempre visível.","Sempre passe a cesta de trabalho por cima das outras máquinas.","Coordene as áreas de trabalho para evitar colisões ou pontos de esmagamento.","A operação simultânea da máquina requer processos de trabalho coordenados e proteção contra colisões ou bloqueios."],"h-einstieg":["Como você entra ou sai da cesta de trabalho?","Você alcança a cesta ao nível do solo.","Suba pela grade externa.","Através do acesso pretendido em uma posição segura de acordo com as instruções de operação.","Através de uma escada colocada ao lado com a lança estendida.","O acesso pretendido e as instruções do fabricante devem ser seguidas; Subir descontroladamente representa risco de queda."],"h-defekt":["O recurso de parada de emergência não funciona. O que você está fazendo?","Você descobrirá o defeito durante a inspeção.","Não utilize a plataforma e relate o defeito.","Continue trabalhando se os controles normais estiverem funcionando.","Tape o interruptor para que ninguém o opere.","A falha de um dispositivo de segurança é um defeito relevante para a segurança e impede uma operação segura."],"h-sicht":["O movimento de condução não pode ser visto devido a um obstáculo. Como você faz isso?","Você deve mover um estágio móvel.","Dirija lentamente sem visibilidade.","Basta confiar no indicador de distância.","Pare o movimento e garanta visibilidade ou instruções seguras de acordo com as instruções de operação.","Antes do procedimento, pessoas, obstáculos e vias de trânsito devem ser vistoriadas com segurança."],"h-rettung":["O que envolve o planejamento de implantação ao trabalhar em alturas maiores?","O palco é usado em uma área remota.","Somente a duração de trabalho planejada.","Um conceito de resgate adequado com pessoas acessíveis e treinadas e procedimentos de descida de emergência.","A suposição de que o corpo de bombeiros resolverá qualquer problema imediatamente.","Um resgate eficaz deve ser organizado antecipadamente, mesmo que os controlos normais falhem."],"k-befaehigung":["O que é necessário para operar um guindaste de forma independente?","Um novo funcionário deverá assumir o trabalho no guindaste.","Adequação e qualificações exigidas, instrução e atribuição correspondente.","Uma carta de condução automóvel é suficiente.","Assistir uma vez é o suficiente.","O trabalho com guindaste só pode ser atribuído a pessoas qualificadas e autorizadas; A instrução do equipamento faz parte disso."],"k-funktionspruefung":["O que é necessário para verificar o guindaste antes do início do turno?","Você assume um guindaste interno.","Basta ler o tempo de execução na placa de identificação.","Verifique as funções relevantes para a segurança e os defeitos visíveis de acordo com as instruções de operação.","Teste o guindaste com carga máxima sem verificação.","O controle operacional obrigatório serve para identificar defeitos perigosos numa fase inicial."],"k-traglast":["Qual é o significado da capacidade de carga permitida?","Uma carga deve ser levantada.","É uma recomendação não vinculativa.","Aplica-se apenas quando o gancho está totalmente retraído.","A capacidade de carga permitida para a respectiva condição operacional não deve ser excedida.","As cargas permitidas para certos tipos de guindastes podem depender do raio, da posição da lança e do armamento."],"k-personen":["O que se aplica às pessoas sob cargas suspensas?","A carga é movida sobre uma área de trabalho.","A área de perigo deve ser mantida desobstruída; ninguém está autorizado a pisar sob a carga suspensa.","Um capacete permite que você fique diretamente abaixo dele.","São permitidas travessias curtas se o guindaste estiver se movendo lentamente.","Cargas suspensas apresentam risco de queda e esmagamento; As pessoas devem ser mantidas fora da área de perigo."],"k-signale":["Você não consegue ver o invasor e recebe sinais contraditórios. O que você está fazendo?","A comunicação não é clara.","Continue o último comando de direção.","Pare o movimento e esclareça claramente a comunicação.","Baixe a carga mais rapidamente, sem consulta.","Movimentos seguros de carga exigem sinais claros e comunicação clara."],"k-sicht":["Quem fornecerá apoio durante o transporte se o operador do guindaste não conseguir ver totalmente o caminho da carga?","Um pilar do corredor obscurece o caminho.","Uma pessoa que passa sem acordo prévio.","Ninguém; apenas o gancho é importante.","Uma pessoa adequada e instruída, com entendimento claramente acordado.","Se o caminho da carga não estiver visível, serão necessárias instruções apropriadas ou outra solução segura."],"k-ruck":["Por que devem ser evitados movimentos bruscos do guindaste?","Uma carga pesada começa a balançar.","Eles criam tensões dinâmicas adicionais e podem desestabilizar a carga.","Eles basicamente reduzem qualquer movimento do pêndulo.","Eles sempre aumentam a capacidade de carga nominal.","As forças de aceleração e frenagem aumentam a tensão no guindaste e nas eslingas."],"k-sperrbereich":["O que você deve verificar antes de balançar uma carga em uma área compartilhada?","Outros funcionários trabalham nas proximidades.","Se a carga corresponde visualmente ao guindaste.","Se a área de perigo está protegida e se nenhuma pessoa está em risco.","Se a carga pode ser transportada o mais alto possível, acima de todos.","Os percursos de rotação e de carga devem estar livres de pessoas desprotegidas."],"k-stuetzen":["O que é crucial para um guindaste móvel com estabilizadores?","Um guindaste é colocado em terreno parcialmente preenchido.","Apenas a largura da estrada.","A cor das placas de suporte.","Base portante, bem como suporte e distribuição de carga conforme instruções de instalação e fabricante.","A instalação tem uma influência significativa na estabilidade, especialmente em condições variáveis ​​do solo."],"k-wetter":["Uma rajada de vento faz com que a carga oscile significativamente. O que é certo?","Você trabalha ao ar livre.","Pare o movimento com segurança e observe as condições operacionais permitidas.","Acelere rapidamente o movimento.","Continue a levantar a carga apesar de exceder os limites do fabricante.","Movimentos de vento e oscilações podem desestabilizar a carga e o guindaste; Os limites de aplicação devem ser respeitados."],"k-freileitung":["O que se aplica ao usar guindastes perto de linhas elétricas aéreas?","A lança ou a carga podem aproximar-se da linha.","Com uma carga não condutiva, as folgas não são importantes.","Esclareça a área de perigo e as medidas de proteção necessárias com os responsáveis ​​antes de iniciar o trabalho.","Confie apenas na reação do próprio operador do guindaste.","Existem perigos de contato e descargas de tensão; são necessárias distâncias de proteção seguras ou outras medidas."],"k-sichern":["O que você faz antes de sair do guindaste?","O trabalho é interrompido.","Deixe a carga suspensa.","Deixe o guindaste sem vigilância com o acionamento em funcionamento.","Baixe a carga com segurança e fixe a grua de acordo com as instruções de operação.","As cargas suspensas não devem ficar descontroladas; A grua e a carga devem estar estacionadas em segurança."],"k-lastanschlag":["Como saber se a tipoia utilizada é adequada?","A carga deve ser elevada com uma cinta de elevação.","Em termos de marcação, capacidade de carga, estado e adequação ao tipo de acessório.","Apenas pela cor da alça de elevação.","Porque já foi usado ontem.","A capacidade e o estado de carga devem ser suficientes, tendo em conta as condições de fixação."],"k-stopp":["Uma pessoa entra inesperadamente no caminho de carga. O que você está fazendo?","O guindaste está atualmente movimentando uma carga.","Pare o movimento imediatamente com segurança e limpe a área de perigo.","Basta dar um sinal de alerta e continuar dirigindo.","Eleve a carga mais alto e passe por cima dela.","As pessoas devem ser protegidas dos movimentos de carga; Se houver um perigo imediato, o movimento deve ser interrompido."],"k-neuerkran":["Você receberá um guindaste com controle desconhecido. O que é certo?","Os controles são diferentes de antes.","Experimente as teclas usuais se você suspeitar.","Permita que outra pessoa sem treinamento siga em frente.","Receba as instruções necessárias relacionadas ao dispositivo antes do uso independente.","Mesmo operadores de guindastes experientes precisam de conhecimento dos controles específicos utilizados, dos dispositivos de proteção e dos limites."],"a-kennzeichnung":["Como você sabe a capacidade de carga permitida de uma eslinga?","Você quer escolher uma tipoia.","O cheiro do material.","Na marcação apropriada e legível da capacidade de carga e nas informações do fabricante.","Sobre a duração do tempo de armazenamento.","A capacidade de carga permitida é determinada pela rotulagem e pelas condições de operação."],"a-sichtpruefung":["Você percebe um corte nítido na alça de elevação. Como você faz isso?","A banda deve carregar uma carga.","Não utilize a fita e envie-a para teste ou rejeição.","Cubra o corte com fita adesiva.","Use-o apenas para cargas particularmente leves.","As fundas têxteis danificadas podem falhar e devem ser avaliadas de acordo com os critérios de descarte."],"a-neigungswinkel":["O que acontece se o ângulo de inclinação dos cabos da eslinga for maior que a vertical?","Um cabide de dois fios se espalha mais.","As forças do fio sempre diminuem.","As forças do cordão permanecem as mesmas.","As forças nos fios aumentam; Os ângulos e capacidades de carga permitidos devem ser respeitados.","À medida que a propagação aumenta, a força de tração por fio de suporte aumenta."],"a-schwerpunkt":["Por que você precisa saber o centro de gravidade da carga?","A carga é acumulada de forma desigual.","Para que a carga permaneça estável ao ser elevada e não tombe incontrolavelmente.","Para selecionar a cor das fundas.","Para que a carga possa ser girada mais rapidamente.","Pontos de fixação desfavoráveis ​​ou a posição do centro de gravidade podem causar tombamento, deslizamento ou declives."],"a-kantenschutz":["Uma cinta de elevação fica encostada na borda afiada de um componente. O que deveria ser feito?","O componente deve ser levantado.","Eleve a carga rapidamente antes que a correia seja danificada.","Use proteção de borda adequada e verifique o tipo de fixação.","Limpe a superfície de carga apenas com um pano.","Bordas afiadas podem danificar as fibras de suporte; o equipamento de amarração deve ser protegido adequadamente."],"a-haken":["Em que você presta atenção ao prender uma tipoia?","Você usa um gancho de carga.","Coloque a tipoia na lateral da ponta do gancho.","Mantenha a aba de segurança permanentemente aberta.","Carregue o gancho conforme pretendido na base do gancho e observe os dispositivos de segurança.","Carga inadmissível na ponta do gancho e falta de fixação podem fazer com que ele seja desenganchado."],"a-knoten":["Você pode encurtar uma cinta de elevação muito longa com um nó?","O comprimento da parada não cabe.","Não; Utilize apenas um tipo de cinta adequado e aprovado ou equipamento de cintagem adequado.","Sim, se o nó estiver bem apertado.","Sim, desde que a carga esteja parada.","Os nós podem enfraquecer significativamente as lingas têxteis e não são permitidos ajustes improvisados ​​de comprimento."],"a-probehub":["Por que uma carga é levantada inicialmente com cuidado?","Você deseja transportar com segurança.","Para que ela possa se deslocar o mais rápido possível.","Para verificar a posição das lingas, estabilidade e centro de gravidade.","Porque a capacidade de carga aumenta automaticamente.","Um primeiro curso controlado ajuda a detectar paradas incorretas e posições de carga instáveis."],"a-lastweg":["Onde as pessoas podem permanecer durante o transporte da carga?","A carga é movimentada com um guindaste.","Diretamente sob a carga com capacete protetor.","Sobre o fardo, se puderem aguentar.","Fora da área de perigo e não sob cargas suspensas.","Mesmo com uma fixação cuidadosa, ainda existem perigos de queda ou oscilação de cargas."],"a-haende":["Como você evita lesões por esmagamento durante o desmame?","A carga se aproxima da superfície de apoio.","Mantenha as mãos e os pés fora da área de esmagamento e utilize meios adequados.","Segure a carga com as mãos nuas.","Fique entre a carga e a parede para corrigir a posição.","Pontos de esmagamento perigosos surgem entre a carga e o suporte."],"a-vierstraenge":["O que se aplica à distribuição de carga numa suspensão de quatro braços sem compensação de carga?","Uma carga rígida está anexada.","Todas as quatro vertentes carregam inevitavelmente a mesma quantidade.","Sem prova de distribuição uniforme, a capacidade de carga não pode ser utilizada como uma estimativa geral para quatro cordões igualmente carregados.","O ângulo de inclinação é então irrelevante.","O carregamento desigual dos fios é possível com cargas rígidas; O projeto e a capacidade de carga admissível devem levar isso em consideração."],"a-chemikalien":["O que se aplica ao usar fundas têxteis em contato com produtos químicos?","Você está trabalhando com um líquido desconhecido.","A cor da pulseira mostra de forma confiável sua durabilidade.","Cada faixa têxtil é resistente a todos os produtos químicos.","Verifique durabilidade e informações do fabricante; Não utilize meios inadequados.","Os produtos químicos podem atacar as lingas e reduzir despercebidamente a sua capacidade de carga."],"a-aufbewahrung":["Como as fundas são armazenadas após o uso?","A missão acabou.","Limpo, seco e protegido contra danos de acordo com as especificações do fabricante.","Preso no chão sob uma carga desprotegida.","Em qualquer gancho afiado ao ar livre.","O armazenamento adequado evita desgaste prematuro e facilita a inspeção visual."],"a-auswahl":["O que deve ser particularmente levado em conta para cargas sensíveis ou com arestas vivas?","Um componente de máquina pintado deve ser movido.","Apenas a velocidade de transporte.","Lingas adequadas e medidas de proteção para a superfície e bordas da carga.","Independentemente da carga, sempre o mesmo cabo de aço.","O tipo de fixação e material devem corresponder à geometria, superfície e perigo."],"a-abstimmung":["O operador do guindaste não tem visão de você. Como você dá instruções?","Você foi designado como atacante.","Você acena à vontade até que um movimento comece.","Você apenas dá uma ligação e vai embora.","Através de sinais claramente acordados ou outra comunicação confiável.","Os invasores e os operadores de guindaste devem comunicar-se claramente; Se não estiver claro, o movimento deve ser interrompido."],"b-qualifikation":["O que uma pessoa precisa para operar uma escavadeira hidráulica com segurança durante a operação?","Uma nova pessoa deve assumir o trabalho no canteiro de obras.","Qualificações apropriadas, instruções relacionadas ao dispositivo e tarefas exigidas.","Apenas uma carteira de motorista de carro.","Apenas uma rápida observação da operação.","O empregador deve garantir as qualificações necessárias e instruir adequadamente o operador para a tarefa."],"b-pruefung":["O que está incluído na inspeção diária da máquina?","Você assume uma escavadeira.","Verifique a cor da pintura e o estofamento do assento.","Inspeção visual e testes funcionais de acordo com as instruções de operação, por exemplo, quanto a vazamentos e danos.","Mova a lança a toda velocidade até parar.","Danos no sistema hidráulico, no chassi e nos dispositivos de segurança podem causar acidentes graves."],"b-leitungen":["O que é preciso saber sobre tubulações subterrâneas antes de escavar?","Você deveria cavar uma vala.","Apenas a profundidade aproximada do poço de escavação planejado.","A cor das marcações acima do solo é suficiente.","Esclarecer a localização de possíveis linhas e determinar medidas adequadas de segurança e exploração.","As tubulações de eletricidade, gás ou água podem ter consequências fatais se danificadas."],"b-schwenkbereich":["Como você protege as pessoas na área de giro da escavadeira?","Você pega material com a lança.","Isole ou proteja a área de perigo e mantenha as pessoas afastadas.","Antes de girar, mova a pá lentamente.","Dirija sobre a área acima das cabeças.","A superestrutura giratória e os implementos criam riscos de esmagamento e impacto."],"b-boeschung":["O que é importante quando se trabalha perto da borda de uma escavação?","A escavadeira está posicionada em terreno estabelecido ou preenchido.","Somente a profundidade de escavação determina o posicionamento permitido.","Preste atenção à capacidade de carga e fixação da borda, bem como às distâncias exigidas de acordo com a avaliação de risco.","Dirija o mais próximo possível da borda para economizar alcance.","Se não houver espaço suficiente ou terreno estável, o aterro poderá falhar e a máquina poderá cair."],"b-standsicherheit":["Por que a inclinação e o terreno são cruciais para o uso?","O canteiro de obras fica em um declive.","A máquina é igualmente estável em qualquer superfície.","Os materiais rodantes sobre esteiras eliminam qualquer risco de tombamento.","Desníveis e declives podem afetar a estabilidade; Observe os limites de aplicação.","A estabilidade e a segurança contra tombamento dependem do piso, do equipamento, da carga e da posição da máquina."],"b-wechselgeraet":["O que você verifica depois de trocar a caçamba de uma escavadeira usando um engate rápido?","Um novo anexo foi instalado.","Se está corretamente travado e protegido de acordo com as instruções de operação.","Apenas se a cor da pá combina.","Se o sistema hidráulico funciona da forma mais silenciosa possível.","Bloqueios defeituosos podem fazer com que os acessórios caiam."],"b-heben":["O que você deve prestar atenção ao levantar uma carga suspensa livremente com uma escavadeira?","A escavadeira é usada para operações de elevação.","Apenas a força de escavação habitual é decisiva.","Observe a carga de elevação permitida, os pontos de fixação adequados e os dispositivos de proteção prescritos.","A carga pode ser enganchada nos dentes da caçamba.","A elevação só é permitida dentro das condições operacionais pretendidas e com equipamento adequado."],"b-rueckwaerts":["Você tem que reverter, mas não consegue ver o caminho. O que é certo?","Outros trabalhadores estão por perto.","Dirija com cuidado e sem visibilidade.","Apenas buzine e continue dirigindo.","Pare, garanta a visibilidade e a área de perigo ou organize instruções adequadas.","A marcha-atrás não deve colocar as pessoas em perigo; a visibilidade limitada requer medidas adicionais."],"b-kabel":["A lança pode chegar perto de uma linha de energia aérea. O que você está fazendo?","Você trabalha em um canteiro de obras apertado.","Esclareça previamente a área de perigo e as medidas de proteção adequadas com os responsáveis.","Ignore a linha se a lança estiver pintada.","Mova a lança apenas com especial rapidez.","Riscos elétricos surgem de contato e descarga elétrica; distâncias seguras e medidas de proteção são necessárias."],"b-verlassen":["Como você estaciona a escavadeira antes de sair?","Você faz uma pausa.","Deixe a lança flutuando livremente.","Coloque o equipamento de trabalho de forma segura e proteja a máquina contra movimentos e uso não autorizado.","Deixe o motor funcionando e a cabine aberta.","Equipamentos de trabalho rebaixados e proteção contra movimentos involuntários reduzem o risco de acidentes."],"b-hydraulik":["Você percebe óleo hidráulico sob alta pressão em uma linha danificada. O que é certo?","Uma linha está vazando.","Sinta o vazamento com a mão.","Anexe uma nova braçadeira sob pressão.","Desligue a máquina com segurança, deixe a pressão ser reduzida e providencie para que as reparações sejam realizadas por pessoal especializado autorizado.","O fluido hidráulico sob alta pressão pode causar ferimentos graves; nunca verifique se há vazamentos manualmente."],"b-unterbau":["Qual é o perigo de dirigir em superfícies instáveis?","O chão fica macio depois da chuva.","A máquina pode afundar, deslizar ou tombar.","A unidade torna-se automaticamente mais larga.","Isso torna o alcance giratório mais seguro.","Uma capacidade de carga insuficiente pode prejudicar significativamente a estabilidade e a segurança de condução."],"b-arbeitsgeraet":["Alguém pode trabalhar sob um implemento elevado?","Uma pessoa quer controlar algo sob a pá.","Sim, quando o motor está em marcha lenta.","Não, não sem o suporte seguro e a fixação necessários do equipamento de trabalho.","Sim, se a pessoa estiver usando capacete de segurança.","Equipamentos hidráulicos podem afundar; O trabalho de manutenção requer equipamento de trabalho seguro."],"b-geraeteart":["Você muda de uma escavadeira hidráulica para uma carregadeira de rodas. O que é necessário?","O comportamento de operação e movimento são diferentes.","Apenas o mesmo calçado.","Um test drive sem instruções.","A qualificação ou instrução exigida para o novo tipo de máquina.","A qualificação deve corresponder ao tipo de máquina utilizada e aos requisitos operacionais específicos."],"g-neigung":["Você está dirigindo uma empilhadeira carregada em um declive. O que é importante?","A rota tem um gradiente claro.","Sempre guie a carga em descidas, mesmo que seja pesada.","Guie a carga em subidas e observe as diretrizes operacionais para dirigir em declives.","Independentemente da direção de deslocamento, levante o garfo ao máximo.","Nas subidas e descidas a carga deve ser transportada sempre em subidas; O veículo e as instruções de operação devem ser observados."],"g-gabelabsenken":["Por que o garfo precisa ser abaixado ao estacionar?","A empilhadeira está estacionada para uma pausa.","Para que outros possam usar o garfo para subir.","Para que o garfo fique mais visível à distância.","Para que o levantamento da carga não represente um risco desnecessário de tropeços ou ferimentos.","Dispositivos de movimentação de carga rebaixados reduzem o risco de acidentes devido a garfos salientes ou não seguros."],"g-fahrerwechsel":["Um colega gostaria de pegar a empilhadeira emprestada. O que deve estar presente?","O colega só tem permissão verbal sua.","Ele deve ter as qualificações necessárias e um mandato empresarial.","Sua própria tarefa também se aplica automaticamente a ele.","Uma carteira de motorista particular é suficiente para qualquer negócio.","A liderança independente está vinculada à adequação pessoal, treinamento, qualificações e atribuição operacional."],"g-ladungssicherung":["Um palete contém caixas soltas e empilhadas. O que é certo?","Uma caixa de papelão pode cair durante a condução.","Proteja a carga contra escorregões e quedas antes do transporte.","Conduza lentamente apenas em terreno particularmente irregular.","Compense caixas soltas com uma posição de garfo mais alta.","A carga deve estar estável e protegida contra quedas antes de ser transportada com o veículo industrial."],"g-bodenbelastung":["À sua frente está um cobertor com capacidade de carga limitada. Como você decide?","A rota passa por um nível intermediário.","Basta prestar atenção ao peso do caminhão sem carga.","Esclarecer a carga de piso permitida para empilhadeiras e cargas.","Dirija com impulso para que o teto fique sob carga por um período de tempo mais curto.","O que é relevante é o estresse real total na área, incluindo veículo, carga e influências dinâmicas."],"g-verkehrswege":["Uma trilha marcada cruza seu caminho. O que é certo?","Os pedestres podem acessar a travessia a qualquer momento.","Você sempre pode reivindicar prioridade com a buzina.","Você está autorizado a passar por cima da marcação sem ser observado.","Ajuste a velocidade, preste atenção aos pedestres e só continue dirigindo quando o caminho estiver livre.","As rotas de trânsito devem ser conduzidas tendo em consideração as pessoas; Os sinais de alerta não substituem a visibilidade segura e uma rota desimpedida."],"g-parkbremse":["Você estaciona uma empilhadeira em terreno plano. O que isso inclui?","Você deseja sair do banco do motorista por alguns minutos.","Estacione, aplique o freio de mão e proteja-o contra uso não autorizado.","Deixe o veículo apenas na posição neutra.","Deixe o garfo na altura da cabeça para que ninguém toque nele.","Antes de partir, o veículo industrial deve ser parado com segurança e protegido contra movimentos involuntários."],"g-typenschild":["Que informações são vinculativas no que diz respeito à carga de uma empilhadeira?","Você quer pegar uma máquina pesada.","A capacidade de carga estimada com base no tamanho do veículo.","As informações do fabricante no diagrama de carga ou capacidade de carga.","O peso do último palete transportado.","A carga admissível é determinada pelas informações do fabricante e depende, entre outras coisas, do centro de carga e da altura de elevação."],"g-tore":["Você se aproxima de uma passagem baixa com uma empilhadeira. O que você está verificando?","Há uma carga enorme no veículo.","Se a passagem, incluindo a carga e o acessório, é possível com segurança.","Apenas a altura do porta-garfos sem carga.","Se você pode dirigir mais rápido antes que o portão feche.","Antes das passagens, devem ser levadas em consideração a altura e a largura livres, bem como as dimensões da carga e do veículo."],"g-reifen":["Durante a sua verificação diária, você encontra um pneu muito danificado. O que você está fazendo?","Danos relevantes para a segurança são visíveis no pneu.","Você dirige devagar até a consulta regular de manutenção.","Você aumenta a pressão dos pneus e continua dirigindo.","Você não coloca o veículo em operação e relata os danos.","Pneus danificados podem prejudicar a estabilidade e o manuseio; o defeito deve ser esclarecido antes do uso."],"h-absperren":["Os funcionários passam por baixo da sua plataforma de trabalho. O que é necessário?","Existe o perigo de queda de ferramentas.","Uma área protetora ou restrita adequada sob o local de trabalho.","Apenas um aviso quando você passar pela primeira vez.","Armazene as ferramentas o mais longe possível da borda da cesta.","Uma área de trabalho sob estações de trabalho elevadas deve ser protegida contra o perigo de queda de peças."],"h-werkzeuge":["Como você transporta ferramentas na cesta de trabalho?","Várias pequenas ferramentas são necessárias em altura.","Coloque-os frouxamente no corrimão para que fiquem de fácil acesso.","Armazene e proteja de forma que não caiam ou impeçam a operação.","Prenda na parte externa do corrimão em seu bolso.","Objetos soltos podem cair e colocar pessoas em perigo; é necessário armazenamento seguro."],"h-abstuetzung":["Um suporte fica em uma tampa de bueiro. O que precisa ser verificado?","Você quer elevar a plataforma.","Apenas certifique-se de que a tampa esteja seca.","Se a carga pode ser absorvida com segurança nesse ponto.","Se os outros suportes não precisam ser usados.","O subsolo e as áreas de contato devem ser capazes de absorver com segurança as forças de apoio; As coberturas devem ser avaliadas separadamente."],"h-notaus":["Quando o dispositivo de parada de emergência deve ser usado?","Um movimento perigoso ocorre imediatamente.","Somente no final de um turno normal.","Para parar em perigo agudo de acordo com as instruções de operação.","Em substituição ao rebaixamento planejado.","A parada de emergência é usada para evitar o perigo, não o controle usual ou o desligamento normal."],"h-schraegstellung":["O aviso de inclinação da platina responde. Como você reage?","A máquina está numa superfície inclinada.","Você ignora o aviso em alturas de trabalho baixas.","Apesar do aviso, você dirige até a posição de elevação mais alta.","Você para e coloca o palco em condições seguras de acordo com as instruções do fabricante.","Os avisos de inclinação podem indicar estabilidade inadequada; movimentos adicionais não devem aumentar o perigo."],"h-umgebung":["O que precisa ser organizado ao instalar perto de uma área de trânsito?","Os veículos podem tocar no palco.","Proteção contra colisões e orientação de trânsito adequada.","Balance a cesta de trabalho o máximo possível sobre a estrada.","Apenas uma chamada de aviso antes de inicializar.","As plataformas aéreas de trabalho devem ser protegidas contra colisões com os utentes da estrada; a instalação deve ser protegida adequadamente."],"h-ueberlast":["O aviso de sobrecarga no cesto é acionado. O que você está fazendo?","Ferramentas adicionais foram convidadas.","Termine o trabalho em velocidade mais alta.","Estabeleça a carga permitida do cesto e siga as instruções do fabricante.","Desligue o sinal de aviso permanentemente.","A carga máxima permitida no cesto, incluindo pessoas e materiais, não deve ser excedida."],"h-quetschen":["Você dirige a cesta sob um teto. Qual perigo é particularmente importante?","Resta pouco espaço acima da cesta.","Aperto ou esmagamento entre o cesto e a estrutura.","Que o motor consome mais combustível.","Que a direção do deslocamento sempre inverte automaticamente.","Espaços apertados acima ou próximos ao cesto de trabalho podem causar ferimentos graves por esmagamento."],"h-stromausfall":["O palco permanece em grande altura sem acionamento principal. O que é certo?","O controle normal da cesta não responde mais.","Você desce a barreira sem segurança.","Você espera até o final do seu turno sem ser informado.","Inicie o resgate preparado utilizando pessoas treinadas e descida de emergência.","O resgate seguro deve ser planeado em caso de perturbações; Pessoas treinadas devem conhecer as funções de emergência."],"h-transportstellung":["Como você prepara o cenário para um transporte?","A plataforma de trabalho aéreo é carregada em um veículo adequado.","Coloque a lança e a plataforma na posição de transporte de acordo com as instruções de operação.","Amarre a plataforma o mais longe possível.","Deixe os suportes estendidos para ocupar mais espaço.","A posição de transporte prescrita e a fixação da carga baseiam-se nas especificações do fabricante e de transporte."],"k-bremsprobe":["O que mostra um teste funcional do freio do guindaste antes do uso?","Você deseja ser capaz de segurar uma carga com segurança.","Se o freio para e mantém o movimento conforme pretendido.","Apenas se a iluminação da cabine funciona.","Se o gancho pode segurar automaticamente uma carga.","Antes da utilização, as funções relevantes para a segurança devem ser verificadas de acordo com as especificações."],"k-schraegzug":["Você consegue puxar uma carga lateralmente em ângulo com o guindaste?","O gancho não está verticalmente acima da carga.","Sim, desde que a grua ainda possua reserva de carga.","Não, as cargas não devem ser puxadas através de trações diagonais inadmissíveis.","Sim, se as fundas forem particularmente curtas.","A tração diagonal pode causar movimentos descontrolados e tensão adicional no guindaste e nas eslingas."],"k-verhakt":["Uma carga está pendurada na subestrutura. O que é certo?","A resistência é sentida ao levantar.","Você continua levantando até que ele desapareça.","Você move a carga lateralmente aos solavancos.","Você para e remove a fixação ou bloqueio com segurança.","Cargas presas não devem ser arrancadas à força, pois podem surgir forças inaceitáveis."],"k-anzuheben":["O que você verifica ao levantar brevemente uma carga suspensa pela primeira vez?","A carga sobe alguns centímetros do solo.","Se ele está equilibrado e a parada é segura.","Se uma pessoa pode colocar-se diretamente sob a carga.","Se o guindaste fica mais estável girando rapidamente.","A elevação controlada breve é ​​usada para verificar a fixação, o equilíbrio e o comportamento seguro da carga."],"k-lastweg":["Onde deve ser a rota de transporte de uma carga de guindaste?","Vários locais de trabalho estão sob o possível caminho de carga.","Se possível, acima das estações de trabalho ocupadas.","Em um caminho planejado e claro, sem pessoas em risco.","Sempre na diagonal pela área mais movimentada.","As rotas de carga devem ser organizadas de forma que as pessoas não corram perigo devido às cargas suspensas."],"k-signalverlust":["A conexão de rádio com o marechal é interrompida. O que você está fazendo?","Você não pode ver o caminho de carregamento em si.","Você continua o movimento lentamente.","Você balança experimentalmente na direção anterior.","Você interrompe o movimento até que haja uma compreensão clara e segura.","Se houver falta de comunicação, o movimento confuso da carga pode não continuar."],"k-haken":["O gancho de segurança não fecha de forma confiável. O que é certo?","Durante a inspeção, é notado um fechamento defeituoso.","O erro deve ser corrigido profissionalmente antes de uso posterior.","Você amarra bem o fecho com uma braçadeira.","Você só usa o gancho para cargas leves.","Dispositivos de fixação defeituosos nos ganchos de carga podem fazer com que as eslingas se desengatem e devem ser corrigidos."],"k-zugrichtung":["O que é importante para o suporte vertical de uma carga?","A carga deve ser levantada de uma máquina.","O gancho do guindaste deve estar alinhado acima do centro de gravidade da carga.","O gancho deve ser posicionado o mais lateralmente possível.","A carga deve ser empurrada antes de ser levantada.","Um efeito de força tão vertical quanto possível acima do centro de carga evita forças laterais inadmissíveis e oscilações descontroladas."],"k-wartung":["Um ruído incomum de trituração é percebido no guindaste. Como você faz isso?","O ruído ocorre ao levantar.","Encobrir o ruído através de maior velocidade.","Interrompa as operações com segurança, relate defeitos e resolva-os.","Continue trabalhando sem aviso prévio até o intervalo.","Alterações visíveis podem indicar danos relevantes para a segurança e exigir uma inspeção."],"k-absetzen":["O que deve ser garantido ao baixar a carga de um guindaste?","Uma carga pesada está posicionada sobre uma superfície.","A carga pode ficar solta em uma superfície inclinada.","As eslingas são removidas enquanto ele ainda está flutuando.","A carga é estável e protegida contra tombamento ou rolamento.","A carga só poderá ser liberada do equipamento de içamento depois de este ter sido assentado com segurança e a estabilidade ter sido estabelecida."],"l-schwerpunkt":["Por que o centro de gravidade precisa ser conhecido antes do golpe?","Uma máquina de formato assimétrico deve ser transportada.","Para que a carga permaneça o mais equilibrada possível durante o levantamento.","Para que as fundas possam ser escolhidas no comprimento desejado.","Para que a capacidade de carga permitida não tenha influência.","A posição do centro de gravidade influencia a distribuição da carga e o equilíbrio seguro durante a elevação."],"l-etikett":["Uma cinta de elevação não possui uma etiqueta legível de capacidade de carga. O que é certo?","A marcação ficou irreconhecível.","Estime a capacidade de carga com base na cor.","Não utilize a cinta de elevação até que a sua adequação tenha sido claramente demonstrada.","Utilize o cinto apenas uma vez para cargas pequenas.","Marcações adequadas são necessárias para eslingas; A capacidade de carga inexplicável impede uma seleção segura."],"l-kantenschutz":["Uma faixa têxtil repousa sobre uma borda afiada de aço. O que é necessário?","A carga tem arestas vivas.","Puxe a faixa o mais firmemente possível sem proteção.","Execute o golpe mais rápido.","Use proteção de borda adequada ou outro equipamento de amarração adequado.","As arestas vivas podem danificar ou cortar as lingas têxteis; é necessária proteção adequada."],"l-spreizwinkel":["Como um ângulo de inclinação maior afeta a carga nas eslingas?","Uma carga é levantada por meio de duas cordas inclinadas.","Em ângulos menos favoráveis, as forças nos fios podem aumentar.","As forças dos fios desaparecem.","O ângulo não tem influência na tensão.","Com um ângulo de parada menos favorável, as forças por fio podem aumentar; As tabelas de capacidade de carga deverão ser observadas."],"l-knoten":["Uma corda de estilingue pode ser encurtada conforme desejado usando um nó?","A corda é demasiado longa para a carga planeada.","Sim, um nó apertado melhora a capacidade de carga.","Não, utilize apenas métodos aprovados de encurtamento e ancoragem.","Sim, se o nó estiver preso com fita adesiva.","Os nós inadmissíveis enfraquecem as lingas e alteram a sua capacidade de carga permitida."],"l-zeichen":["O que se aplica à comunicação com a pessoa que opera a grua?","O caminho de carga está parcialmente obscurecido.","Várias pessoas emitem sinais diferentes ao mesmo tempo.","São utilizados sinais claros e previamente acordados.","A comunicação nunca é necessária com guindastes de rádio.","Sinais claros e responsabilidades claras evitam movimentos incorretos e perigosos."],"l-sichtpruefung":["Quando as eslingas devem ser verificadas quanto a defeitos visíveis?","Você deseja usar uma corrente de tipoia.","Antes de usar, preste atenção a qualquer dano visível externamente.","Somente se um acidente já tiver acontecido.","Apenas uma vez na primeira compra.","Antes de cada utilização, devem ser avaliadas as condições seguras de trabalho; Danos visíveis impedem o uso seguro."],"l-drehung":["Uma carga levantada começa a girar incontrolavelmente. O que você está fazendo?","A carga se move no caminho da carga.","Você coloca a mão entre a carga e a parede.","Você se coloca sob o fardo e se agarra a ele.","Você mantém distância e deixa o movimento parar de forma controlada.","Movimentos descontrolados de carga criam riscos de esmagamento e impacto; As pessoas devem sair da área de perigo."],"l-ablegen":["Quando as eslingas podem ser removidas da carga?","A carga é colocada em cavaletes.","Se a carga estiver estável e protegida contra tombamento ou rolamento.","Assim que tocar o solo pela primeira vez, independentemente da sua posição.","Enquanto ainda paira para economizar tempo.","As eslingas só podem ser removidas depois de terem sido colocadas de forma segura e estável."],"l-ketten":["Uma eslinga de corrente tem um elo muito torto. O que você está fazendo?","O dano é visível antes mesmo do levantamento.","Enrole a área danificada com arame.","Retire a corrente de uso e leve-a para verificação profissional.","Eleve a carga apenas até metade da altura.","Elos de corrente deformados são danos visíveis que podem impedir o uso seguro."],"b-einweiser":["O que é importante quando a visibilidade da escavadeira é limitada?","Uma parte do edifício obscurece a área de condução.","Medidas ou instruções visuais apropriadas e comunicação clara.","Basta observar o capô.","Dirija pela área giratória apesar de estar invisível.","Se a visibilidade for restrita, os perigos devem ser evitados através de medidas organizacionais e técnicas adicionais."],"b-aushub":["Onde o material escavado pode ser armazenado perto de um poço de construção?","A borda do poço não deve ser colocada em risco adicional.","Empilhe-os diretamente na borda para que as calçadas permaneçam desimpedidas.","Armazenar a uma distância suficientemente segura e de acordo com as especificações do local de construção.","Coloque sobre escoramento solto sem testes adicionais.","O material escavado pode pôr em perigo aterros e escoramentos devido a cargas adicionais; As distâncias de segurança devem ser mantidas."],"b-personen":["As pessoas podem permanecer na área de balanço enquanto a escavadeira estiver em movimento?","Uma pessoa deseja medir enquanto faz panorâmica.","Sim, desde que ela use capacete de segurança.","Sim, se a escavadeira balançar lentamente.","Não, a área de perigo deve estar livre antes do movimento.","Existe risco de ferimentos graves por esmagamento e impacto na área giratória; a área deve ser mantida limpa."],"b-ladung":["Como você transporta material com segurança com uma carregadeira de rodas?","Uma pá cheia deve ser conduzida pelo quintal.","Com uma posição de transporte baixa adequada e um caminho livre.","Com pá elevada para melhor visibilidade.","Com portas abertas e forte ângulo de direção.","Uma posição de transporte adequada reduz o risco de capotamento e melhora a estabilidade de condução."],"b-anbaupruefung":["O que você verifica após acoplar um anexo?","Uma nova pá foi anexada.","Apenas a limpeza da pintura.","O travamento seguro e o funcionamento de acordo com as instruções de operação.","Apenas se o dispositivo parece o mesmo visto de fora.","Bloqueios incorretos em engates rápidos podem levar à liberação involuntária de acessórios."],"b-einstieg":["Como você entra na cabine da escavadeira com segurança?","Os degraus ficam sujos depois da chuva.","Suba na cabine pela lança.","Suba nas lagartas com um salto.","Use degraus e pegas designados e limpe degraus sujos.","Subidas adequadas e pontos de apoio seguros reduzem o risco de escorregar e cair."],"b-graben":["Uma parede de trincheira apresenta rachaduras e está desmoronando. O que é certo?","Você trabalha bem próximo à vala.","Pare o trabalho e peça aos responsáveis ​​que protejam o poço de escavação.","Basta dirigir mais perto da borda para fechar a vala.","Aprofunde ainda mais a trincheira sem proteção.","Rachaduras e movimentos do solo podem indicar instabilidade e exigir avaliação de segurança adicional."],"b-betanken":["Em que você presta atenção ao reabastecer uma máquina de terraplenagem?","O tanque está quase vazio.","Proteja o motor e as fontes de ignição de acordo com as instruções do fabricante e evite derramamentos.","Sempre reabasteça gasolina ou diesel na cabine.","Fume durante o reabastecimento quando não há vento.","Os riscos ambientais e de incêndio durante o manuseio do combustível exigem medidas de proteção adequadas."],"b-laufwerk":["Por que os trilhos e o material rodante precisam ser verificados regularmente?","Você percebe vibrações incomuns enquanto dirige.","Para que a máquina possa se mover mais rápido.","Porque os danos podem afetar a orientação segura e a estabilidade.","Porque o trabalho é sempre permitido sem inspeção visual.","Danos ao acionamento podem afetar a capacidade de manobra, a estabilidade e a operação segura."],"b-einweisen":["O que é necessário ao trabalhar próximo ao tráfego público de pedestres?","Uma escavadeira trabalha diretamente na beira de uma calçada.","Os pedestres devem passar eles próprios pela área de balanço.","Basta colar uma placa na pá.","Isolar eficazmente a área de perigo e direcionar o tráfego com segurança.","Terceiros não devem entrar na zona de perigo das máquinas de terraplenagem; São necessárias barreiras adequadas e roteamento de tráfego."],"g2-fahrweg":["Há líquido derramado na estrada à frente. Como você faz isso?","A empilhadeira passaria diretamente sobre a área escorregadia.","Pare de dirigir e mande proteger ou remover o local de perigo.","Passe pelo local o mais rápido possível com o garfo levantado.","Espere por pneus mais secos e continue dirigindo inalterado.","Rotas contaminadas colocam em risco a estabilidade e devem ser adequadamente protegidas antes de circular nelas."],"g2-sichtladung":["Uma palete alta bloqueia a visão à frente. O que é certo?","Você tem que dirigir até uma área de armazenamento e não consegue ver a rota.","Levante o palete até poder ver por baixo dele.","Dirija apenas usando métodos apropriados e seguros, como fazer marcha-atrás com visão desimpedida.","Você ainda pode dirigir na estrada sem uma placa de sinalização ou uma visão clara.","A direção de deslocamento e a visibilidade devem permitir a observação segura da rota de tráfego; As cargas não devem substituir a inspeção visual."],"g2-fussgaengerstop":["Um pedestre para ao lado da empilhadeira. O que você está fazendo?","A pessoa está dentro do alcance possível de condução e rotação.","Ultrapassar o pedestre acelerando brevemente.","Passe pela pessoa com a carga levantada.","Pare e continue dirigindo apenas a uma distância segura.","As pessoas devem permanecer fora da área de perigo; Se necessário, a viagem deverá ser interrompida."],"g2-hubmast":["Você percebe uma linha hidráulica danificada no mastro de elevação. O que se aplica?","O óleo hidráulico está visivelmente vazando do implemento.","Retire a empilhadeira de operação e relate os danos.","Verifique o vazamento manualmente durante o levantamento.","Levante apenas cargas menores até o final do turno.","Danos hidráulicos podem provocar movimentos descontrolados; o uso seguro não é garantido até o teste."],"g2-lagerregal":["Você deseja armazenar um palete em uma prateleira. O que você verifica primeiro?","O nível da prateleira é alto e a capacidade de carga deve ser mantida.","Empurre o palete para a prateleira o mais rápido possível.","Verifique se o compartimento da prateleira, o peso da carga e o espaço de armazenamento livre são adequados.","Estime o peso total com base apenas no número de caixas.","As prateleiras e os equipamentos de transporte de carga devem corresponder à situação de carga e armazenamento."],"g2-batterieschaden":["A bateria de uma empilhadeira está danificada externamente. O que é certo?","Antes do carregamento, são notadas rachaduras ou fluido incomum.","Cubra os danos com fita adesiva e carregue imediatamente.","Deixe outra pessoa carregar a bateria sem verificá-la.","Não carregue nem utilize e informe os especialistas responsáveis.","Baterias danificadas representam riscos elétricos e químicos e requerem avaliação profissional."],"g2-fahrerkabine":["O que se aplica a objetos soltos na área do motorista?","As ferramentas estão no chão ao lado dos pedais de controle.","Remova objetos e mantenha a área de operação limpa.","Segure a ferramenta apenas com um pé enquanto dirige.","Esconda as peças soltas sob o banco do motorista.","Objetos soltos podem bloquear os pedais e prejudicar a operação segura do veículo."],"g2-uebergabe":["Você assume uma empilhadeira após uma mudança de turno. O que isso inclui?","Um colega usou o veículo pela última vez.","Suponha que o colega tenha assumido todas as verificações.","Faça a inspeção necessária e informe-se sobre defeitos conhecidos.","Comece a viagem sem olhar para a máquina.","A pessoa que assume o controle deve garantir que ele esteja em condições seguras antes do uso."],"g2-transportsicherung":["Um objeto alto está solto no palete. Como você age?","A carga pode tombar para a frente durante a travagem.","Leve o garfo particularmente alto para que a carga permaneça estável.","Basta fazer as curvas devagar, seguir em frente mais rápido.","Configure a carga de forma estável e proteja-a contra tombamento ou queda.","As cargas soltas devem ser estabilizadas antes do transporte para que os movimentos de travagem e de condução não provoquem a sua queda."],"g2-arbeitsende":["O que é importante com uma empilhadeira autônoma?","Você termina seu turno e sai da área.","Estacione o veículo com segurança e proteja-o contra deslocamento e uso não autorizado.","Deixe a chave inserida para que os colegas possam encontrar a máquina.","Deixe o garfo na altura dos olhos para que fique visível.","O estacionamento seguro inclui manuseio de carga rebaixado e proteção contra movimento e comissionamento não autorizado."],"g2-bremsweg":["Por que você deve prestar atenção especial à distância de frenagem sob carga?","A empilhadeira transporta mercadorias pesadas através de um corredor de armazém.","Sempre freie mais tarde com uma carga pesada do que sem carga.","Ajuste a velocidade às condições de visibilidade, solo e carga.","Ao frear, eleve a carga bruscamente para desacelerar melhor.","A massa e as condições da estrada influenciam a distância de parada; a velocidade adaptada é fundamental."],"g2-rampe":["O que você verifica antes de subir uma rampa íngreme?","O percurso pode ser muito íngreme para o veículo.","Dirija na rampa em velocidade máxima, independentemente da inclinação.","Passe pela borda da rampa com a carga elevada.","Verifique a inclinação permitida e o modo de operação seguro nas especificações do veículo.","Somente poderão ser utilizadas rampas dentro dos limites operacionais pretendidos; As instruções de operação e o controle de carga são decisivos."],"g2-zinke":["Um palete é mais largo que a distância do garfo. O que precisa ser levado em consideração?","Você planeja assumir uma carga incomumente grande.","Ajuste a distância do garfo e os pontos de montagem de acordo com a carga.","Utilize apenas um dente se a carga for muito larga.","Eleve a carga em ângulo até atingir a posição correta.","A absorção de carga uniforme e adequada reduz escorregões e tombamento."],"g2-betriebsanweisung":["Qual é o papel da regulação operacional do tráfego?","Áreas marcadas de sentido único e pedonal aplicam-se no armazém.","Com empilhadeiras, apenas se aplicam as regras da via pública.","Siga as rotas e regras de trânsito especificadas.","Ignore as marcações quando o veículo estiver carregado.","As rotas e regras de segurança da empresa protegem o tráfego de empilhadeiras e as pessoas a pé."],"g2-nothalt":["A direção reage de forma incomum durante a condução. O que é certo?","O veículo não pode mais ser controlado normalmente.","Dirija em velocidades mais altas para tornar a direção mais responsiva.","Compense o erro com deflexões de direção particularmente grandes.","Pare em um local seguro e mande verificar o veículo.","A direção prejudicada põe em risco a orientação segura; a máquina não deve continuar a ser operada de forma descontrolada."],"g2-anschlagkette":["Você deseja mover uma carga suspensa livremente com uma empilhadeira. O que se aplica?","A carga deve ficar pendurada em um gancho sob os garfos.","Somente com um dispositivo aprovado e equipamento de transporte de carga adequado.","Qualquer corrente serve se a carga não for pesada.","Prenda a corrente diretamente entre os dois garfos.","Cargas suspensas livremente alteram a estabilidade; São necessárias aprovações do fabricante e instalações adequadas."],"g2-rollenlast":["Um componente cilíndrico está solto em um palete. O que você está fazendo?","A carga pode rolar durante o transporte.","Aproxime-se da palete de forma particularmente brusca.","Proteja o componente contra rolamento antes da palete ser recolhida.","Posicione os dentes suficientemente altos para que o componente não fique visível.","Cargas redondas ou rolantes requerem proteção confiável contra mudanças de posição."],"g2-pruefplakette":["Como saber se a empilhadeira pode ser usada?","Há um adesivo de inspeção colado na máquina.","Qualquer adesivo sempre substitui a inspeção visual diária.","A falta de folga pode ser substituída por uma condução cuidadosa.","Além da verificação do veículo, deve-se levar em consideração o status de teste válido e a aprovação operacional.","Testes recorrentes e controles operacionais diários cumprem diferentes funções de segurança."],"g2-licht":["A iluminação do armazém apagou-se repentinamente. O que é certo?","Você não pode mais ver os obstáculos no caminho com segurança.","Pare de dirigir até que a visibilidade segura seja garantida.","Aumente a velocidade de condução para sair da área escura.","Continue dirigindo com os garfos levantados sem inspeção visual.","Um percurso que não pode ser ignorado com segurança não deve ser percorrido sem medidas de segurança eficazes."],"g2-ueberhang":["Uma carga se estende muito além da lateral do garfo. O que você está verificando?","Pretende transportar a palete através de uma porta estreita.","Compense a projeção lateral com uma curva rápida.","Avalie a folga, a estabilidade e a capacidade de carga permitida antes de dirigir.","Conduza a carga à velocidade máxima, independentemente da sua forma.","As saliências aumentam os riscos de colisão e podem alterar a estabilidade e o espaço de tráfego necessário."],"g2-wartungsbereich":["Existem barreiras em frente a uma área de manutenção. Como você está se comportando?","Sua rota habitual está temporariamente fechada.","Mova as barreiras brevemente e passe despercebido.","Dirija diretamente pela área de trabalho sob carga.","Observe o encerramento e escolha uma rota alternativa aprovada.","As áreas isoladas não podem ser acessadas ou atravessadas sem permissão."],"g2-bremsprobe":["Quando faz sentido um teste funcional do freio de serviço?","Você prepara a empilhadeira antes do trabalho.","Como parte da inspeção necessária antes do uso.","Realize somente após um acidente grave.","Somente se o caminhão já tiver atingido alta velocidade.","A funcionalidade das instalações relevantes para a segurança é verificada antes da utilização."],"g2-fahrzeuganhaenger":["Você quer puxar um trailer com uma empilhadeira. O que é necessário?","A empresa está planejando o transporte com carga acoplada.","Amarre cada trailer a um garfo sem verificar.","Observe a aprovação do fabricante, o acoplamento adequado e a carga de tração admissível.","Basta aumentar a pressão dos pneus e partir.","A operação do trem só é possível com segurança dentro das especificações técnicas e com uma conexão adequada."],"g2-rueckfahrt":["O que é importante ao fazer marcha-atrás com a empilhadeira?","Há uma área confusa no corredor do armazém.","Olhe sempre apenas pelo retrovisor, independentemente do ambiente.","Dirija sem visibilidade enquanto a buzina for pressionada uma vez.","Observe com segurança o percurso e a área de pessoas e, se necessário, oriente-as.","A marcha-atrás requer uma visão clara ou medidas de segurança adicionais eficazes."],"g2-lastentnahme":["Você tira um palete de uma prateleira alta. O que é certo?","A paleta pode não estar centralizada.","Pegue a carga com segurança e estabilize-a antes de baixá-la.","Deixe o palete balançar para o lado ao puxá-lo.","Verifique embaixo do palete elevado para ver se está danificado.","A elevação e a descida controladas evitam quedas de cargas e movimentos perigosos."],"h2-absenkweg":["Por que a área sob uma plataforma aérea de trabalho deve permanecer limpa?","A cesta é baixada e os materiais são colocados embaixo dela.","Pressione os materiais com a cesta.","Fique de olho apenas na área dos pés do operador.","Evite o risco de esmagamento e colisão ao baixar.","A área de descida não deve conter pessoas ou obstáculos que possam ficar presos."],"h2-transporthoehe":["Como você move um palco móvel por uma passagem baixa?","A folga é inferior à da lança estendida.","Coloque a plataforma numa posição de transporte adequada de acordo com as instruções de operação.","Deixe a lança estendida e mova-se sob o teto.","Pressione o cesto contra a lateral da moldura da porta.","Para movimentos de deslocamento, a altura total e a posição de transporte devem corresponder às especificações do fabricante e à passagem."],"h2-bodenoeffnung":["Há uma abertura não segura no chão próximo ao palco. Como você reage?","Um ponto de condução ou apoio está localizado próximo à abertura.","Coloque um suporte diretamente na borda da abertura.","Altere o local de instalação ou mande verificar a capacidade de carga e a fixação por um profissional.","Cubra o ponto de perigo apenas com uma caixa de papelão.","Aberturas e áreas de borda podem falhar sob cargas de suporte e devem ser levadas em consideração de forma eficaz."],"h2-rettungsperson":["Por que uma segunda pessoa precisa estar familiarizada com o procedimento de resgate?","Um operador pode ficar incapacitado no topo.","Portanto, esse trabalho na cesta geralmente pode ocorrer sem segurança.","Para que o estágio possa ser operado mais rápido do que o permitido.","Para que um resgate seguro possa ser iniciado em caso de emergência.","Um conceito de resgate deve levar em conta a assistência terrestre em caso de falha ou emergência."],"h2-werkzeugabwurf":["O que se aplica a ferramentas em grandes altitudes?","Uma ferramenta solta pode cair da borda do cesto.","Ferramentas seguras para que não coloquem ninguém em perigo ou caiam.","Basta colocar ferramentas no corrimão para reduzir a carga.","Se necessário, jogue as ferramentas da cesta.","A queda de objetos coloca em perigo as pessoas abaixo; O material deve ser armazenado com segurança."],"h2-trittstufe":["Uma caixa deve servir como espaço adicional na cesta. O que é certo?","Caso contrário, você mal chegará ao local de trabalho.","Coloque a caixa no corrimão e suba nela.","Não suba em elevações improvisadas; Utilize equipamento de trabalho adequado.","Carregue intencionalmente o cesto além da altura permitida.","Elevações improvisadas prejudicam a proteção contra quedas pretendida e não são permitidas."],"h2-lastverteilen":["No que você presta atenção quando tem várias pessoas na cesta de trabalho?","Duas pessoas trabalham na cesta com ferramentas pesadas.","Julgue a carga com base apenas no tamanho da ferramenta.","Armazene ferramentas pesadas diretamente na grade de proteção.","Não exceda a carga permitida do cesto, incluindo pessoas e ferramentas.","A capacidade de carga permitida inclui todas as pessoas, materiais e ferramentas no cesto."],"h2-abstuetzplatte":["Quando são considerados calços adicionais para suportes?","O piso de instalação só pode suportar uma carga limitada.","Se isso for necessário para uma distribuição segura da carga de acordo com as especificações.","Para colocar os suportes o mais próximo possível da borda de um poço de construção.","Para usar um alcance maior sem informações do fabricante.","São necessárias áreas de contato suficientes para forças de apoio seguras."],"h2-baugrube":["Um palco deve estar localizado diretamente na borda de um poço de construção. O que você está verificando?","O subsolo pode ceder lateralmente devido ao poço de escavação.","Estenda os suportes no poço de escavação.","Garanta distância de segurança suficiente e capacidade de carga do subsolo.","Compense o risco apenas levantando o cesto lentamente.","Os poços de escavação podem afetar a estabilidade devido à falha do talude e do subsolo."],"h2-witterung":["A cobertura se instala durante o uso. Como você age?","As superfícies de controle e a área de trabalho ficam lisas.","Eleve o palco para evitar neve e gelo.","Ignore os avisos enquanto a plataforma estiver acesa.","Interrompa o trabalho e reavalie as condições operacionais de acordo com as instruções de operação.","Mudanças climáticas podem alterar a responsabilidade, a operabilidade e os limites seguros de uso."],"h2-aufbaukontakt":["Uma construção em aço limita o percurso do cesto. O que é importante?","Ao levantar existe o risco de esmagamento entre o cesto e o transportador.","Planeje os movimentos para que seu corpo e a cesta não fiquem presos.","Torne a viagem mais rápida para que a cesta passe mais rapidamente.","Empurre a construção com o cesto para o lado.","Os pontos de esmagamento entre a plataforma e o ambiente requerem observação cuidadosa e movimento controlado."],"h2-sicherheitsabstand":["Quando a área de perigo de uma etapa deve ser isolada?","Uma rota de transporte público passa sob o local.","Somente se um objeto já tiver caído.","Se terceiros puderem ser colocados em perigo pelo movimento ou queda de objetos.","Nunca, pois o cesto de trabalho basicamente evita todos os perigos.","A área abaixo e próxima ao palco deve ser protegida contra perigos previsíveis."],"h2-korbtor":["O que se aplica à porta de entrada do cesto de trabalho?","Você já está na altura de trabalho.","Deixe a porta aberta para poder sair mais rápido.","Amarre a porta permanentemente aberta com uma corda.","Mantenha a porta fechada de acordo com o mecanismo de travamento fornecido.","As travas fornecidas fazem parte das medidas de proteção contra queda da gaiola de trabalho."],"h2-energieleitung":["O que se aplica se uma linha aérea não for desligada com segurança?","Você trabalha com a plataforma de trabalho aérea próxima a eles.","Garanta as distâncias de segurança especificadas e as medidas de proteção necessárias.","Mova a cesta bem na frente da linha, desde que ela não seja tocada.","Confie nos pneus de plástico e trabalhe sem folgas.","As descargas elétricas também são possíveis sem contato direto; São necessárias distâncias de segurança."],"h2-schwanken":["A cesta de trabalho começa a balançar com força incomum. O que é certo?","O movimento não é mais controlado.","Reajuste incontrolavelmente com contramovimentos rápidos.","Pare o movimento e verifique a causa ou as condições de operação.","Adicione pessoas extras à cesta para torná-la mais pesada.","Vibrações incomuns podem indicar condições operacionais inadequadas ou mau funcionamento."],"h2-ladegeraet":["Um cabo de carregamento para o estágio operado eletricamente está danificado. O que você está fazendo?","Ao conectar, o isolamento danificado é visível.","Toque no dano com luvas molhadas.","Pressione o plugue na tomada com a maior força possível.","Não inicie o processo de carregamento e mande verificar o cabo por um profissional.","A fiação elétrica danificada representa risco de choque elétrico e incêndio."],"h2-gelaenderanbau":["Você mesmo pode remover uma grade para se aproximar?","Um componente impede que pessoas se aproximem do local de trabalho.","Não modifique ou remova dispositivos de proteção por conta própria.","Após levantar, desparafuse o corrimão e instale-o posteriormente.","Continue trabalhando sem grade enquanto alguém estiver próximo a ela.","Os dispositivos de proteção estrutural não podem ser alterados sem especificações permitidas e medidas de substituição seguras."],"h2-lastkran":["A plataforma pode ser usada como guindaste para levantar uma carga?","O material deverá ser transportado pendurado livremente próximo ao cesto de trabalho.","Sempre que o peso for inferior ao seu próprio peso corporal.","Somente se o fabricante e o equipamento permitirem expressamente este uso especial.","Basta prender um gancho no corrimão e levantar o material.","As plataformas de trabalho aéreo não são automaticamente projetadas para trabalho com guindaste ou cargas suspensas adicionais."],"h2-arbeitsvorbereitung":["O que é necessário para se preparar para um novo local?","Você ainda não conhece o canteiro de obras.","Basta estimar a distância até o estacionamento mais próximo.","Independentemente do ambiente, estenda-o completamente imediatamente.","Avaliar perigos, solo, rotas de tráfego, resgate e adequação de equipamentos.","Uma avaliação de riscos relacionada à localização é um pré-requisito para condições operacionais seguras."],"h2-kabelschlaufe":["Um cabo de alimentação atravessa o caminho do palco. O que é certo?","O cabo pode ficar preso durante o movimento.","Limpe a estrada e proteja os cabos elétricos contra danos.","Use o cabo com as rodas como soleira da estrada.","Levante o cesto sem verificar a área do piso.","Cabos atropelados ou esmagados podem causar riscos elétricos e mecânicos."],"h2-leitungsnaehe":["Quem esclarece as medidas de proteção de um sistema elétrico?","A plataforma deve funcionar próxima a equipamentos energizados.","A pessoa na cesta decide apenas a olho nu.","Envolver as autoridades responsáveis ​​e implementar medidas de proteção coordenadas.","A distância só será determinada após o início dos trabalhos.","Trabalhar próximo a sistemas elétricos requer medidas de proteção planejadas e coordenadas."],"h2-funkkommunikation":["Porque é que os sinais entre o chão e o cesto têm de ser claros?","Uma pessoa no solo auxilia nas manobras.","Para que várias pessoas possam dar instruções contraditórias ao mesmo tempo.","Para que o abaixamento de emergência possa ser experimentado sem instruções.","Para que os movimentos só sejam realizados após uma comunicação clara.","A comunicação clara reduz movimentos incorretos e colisões durante manobras."],"h2-neuebedienung":["Você muda para um tipo diferente de estágio. O que é necessário?","As funções operacionais diferem significativamente.","Instruções específicas do dispositivo antes do uso independente.","Basta ler o logotipo da empresa no dispositivo.","Um test drive com a cesta já estendida sem instruções.","A qualificação por si só não substitui a instrução no tipo de dispositivo específico."],"h2-steckanschluss":["O que você deve verificar antes de conectar um carregador?","Uma plataforma de trabalho aéreo elétrica precisa ser carregada.","Use qualquer soquete, independentemente da condição e do fusível.","Verifique a conexão adequada e o cabo não danificado de acordo com as instruções do fabricante.","Desconecte o plugue de alimentação regularmente durante o carregamento.","Conexões elétricas adequadas e intactas protegem contra choque elétrico e incêndio."],"h2-absperrpersonal":["Uma pessoa entra na área isolada durante o trabalho de elevação. O que você está fazendo?","Você pode ver uma pessoa diretamente abaixo da cesta de trabalho.","Continue dirigindo se a pessoa estiver usando capacete de proteção.","Deixe cair uma ferramenta na direção deles como um sinal de alerta.","Pare o movimento perigoso e limpe a área.","Uma barreira não substitui a observação da área de perigo durante a operação."],"k2-arbeitsplanung":["O que deve ser incluído na preparação do trabalho antes da operação do guindaste?","Carga, localização e rota de transporte ainda não foram coordenadas.","Levante primeiro a carga mais pesada, sem planejamento adicional.","Marque apenas o caminho mais curto no chão do corredor.","Esclareça antecipadamente a capacidade de carga, eslingas, caminho de carga e área de perigo.","Um movimento planejado do guindaste requer manuseio de carga adequado, rotas seguras e medidas de proteção coordenadas."],"k2-hakenposition":["Como o gancho do guindaste é posicionado sobre a carga antes do levantamento?","Os pontos de fixação estão abaixo do guindaste.","O mais verticalmente possível acima do centro de gravidade de acordo com o batente.","Desloque-se bem para o lado para que a carga oscile mais rapidamente.","Em qualquer caso, na extremidade exterior da carga, independentemente do centro de gravidade.","A aplicação vertical de força e pontos de ancoragem adequados reduzem movimentos laterais e movimentos descontrolados."],"k2-hakengabel":["Um gancho de carga mostra uma deformação perceptível. O que se aplica?","O gancho parece dobrado em relação ao seu estado normal.","Dobre a deformação para trás com a próxima carga.","Pare a operação do guindaste e leve o gancho para ser verificado por um especialista.","Anexe apenas cargas leves e continue trabalhando.","A deformação pode afetar a segurança do gancho; uso posterior não autorizado não é permitido."],"k2-zugueberlast":["O fardo é mais pesado do que inicialmente assumido. O que você está fazendo?","Novas informações de peso surgem durante a preparação.","Substitua a reserva de segurança por uma elevação mais rápida.","Ignore o peso da carga fixando-a em outro ponto.","Determine a carga real e verifique novamente os limites de carga.","A elevação segura requer dados de carga confiáveis ​​e conformidade com todas as capacidades de carga relevantes."],"k2-arbeitskorb":["Um gancho de guindaste comum pode transportar pessoas facilmente?","Uma pessoa deseja chegar a um local de trabalho elevado.","Não, o transporte de passageiros requer instalações e medidas especiais permitidas.","Sim, se a pessoa se segurar na corda.","Sim, assim que o golpe for realizado de forma particularmente lenta.","O transporte de pessoas só é permitido em condições especiais previstas para o efeito."],"k2-bruecke":["Uma ponte rolante se move ao longo de um corredor compartilhado. O que é importante?","Os funcionários ficam sob a rota de transporte.","Dirija com a carga logo acima da cabeça dos funcionários.","Mantenha efetivamente a rota de carga e a área de tráfego limpas e seguras.","Use apenas a buzina de advertência em vez de outras medidas.","As pessoas em risco não devem estar sob cargas suspensas ou no seu caminho de transporte."],"k2-zweitekrane":["Dois guindastes trabalham em uma área sobreposta. O que é necessário?","As lanças ou cargas podem colidir umas com as outras.","Ambos os operadores de guindaste trabalham ao mesmo tempo sem acordo prévio.","Os movimentos são deliberadamente acelerados para evitar cruzamentos.","Coordenar as operações e tomar medidas apropriadas para prevenir ameaças mútuas.","As áreas de trabalho sobrepostas exigem uma organização operacional coordenada e salvaguardas adequadas."],"k2-pruefbuch":["Qual é o significado da inspeção recorrente obrigatória de guindastes?","A máquina é usada regularmente em operações.","Complementa o controle operacional com a perícia prescrita.","Substitui permanentemente qualquer inspeção visual antes do início do trabalho.","Só é necessário após uma falha.","As inspeções recorrentes e os controles operacionais contínuos têm tarefas diferentes."],"k2-absetzflaeche":["A área de colocação pretendida é irregular. Como você age?","A carga pode tombar quando colocada.","Coloque a carga em um canto e deixe-a pendurada inalterada.","Prepare bases ou superfícies adequadas, resistentes e estáveis.","Coloque uma pessoa sob a carga durante a descida.","As áreas de colocação devem suportar a carga com segurança e evitar movimentos perigosos de tombamento ou rolamento."],"k2-anfahrbereich":["Antes do guindaste começar a se mover, há uma pessoa na área de deslocamento. O que você está fazendo?","A rota está bloqueada por uma pessoa.","Afaste a pessoa com um pequeno test drive.","Afaste-se usando apenas o interruptor de limite sem inspeção visual.","Inicie o movimento apenas quando a área de perigo estiver livre e segura.","Os movimentos de condução e de rotação não devem colocar as pessoas em perigo."],"k2-schlaffseil":["Por que o cabo de elevação não deveria ficar incontrolavelmente frouxo quando é baixado?","A carga está colocada, o gancho é abaixado ainda mais.","Para que a corda e os ganchos não fiquem presos ou sujeitos a cargas descontroladas.","Para que a carga possa ser puxada lateralmente pela corda.","Para que as fundas se soltem do gancho.","O roteamento descontrolado de cabos pode causar emaranhados e movimentos de carga perigosos."],"k2-pendel":["Uma carga transportada começa a balançar. O que é certo?","A carga se move lateralmente mais do que o planejado.","Compense com contra-movimentos rápidos e velocidade total.","Reduza os movimentos de forma controlada e acalme o deslocamento sem pessoas na área de perigo.","Segure a carga oscilante com as próprias mãos.","Cargas oscilantes podem afetar pessoas e instalações; movimentos calmos reduzem o risco."],"k2-funkakku":["O controle via rádio de um guindaste está com a bateria fraca. O que se aplica?","A conexão pode quebrar durante a elevação.","Levante uma carga rapidamente antes que o controle falhe.","Se a conexão for perdida, mova a carga puxando a eslinga.","Garanta uma conexão de controle confiável antes do uso.","Controle e comunicação confiáveis ​​são pré-requisitos para movimentos controlados do guindaste."],"k2-mehrereanschlaeger":["Duas pessoas dão sinais diferentes ao operador do guindaste ao mesmo tempo. O que é certo?","Os sinais se contradizem.","Interrompa o movimento e esclareça a responsabilidade clara.","Prefira o sinal da pessoa mais distante.","Continue o movimento de acordo com seu próprio sentimento.","Os condutores de guindastes precisam de uma comunicação clara e inequívoca, especialmente quando as rotas de carga são confusas."],"k2-endabschaltung":["Por que uma chave fim de curso não deveria ser usada indevidamente como uma limitação de curso normal?","A carga é frequentemente movida até a distância máxima de elevação.","Os interruptores de limite geralmente permitem uma elevação mais rápida sem visibilidade.","Os interruptores de limite são dispositivos de segurança e não substituem a operação controlada.","Eles devem ser atingidos com a maior força possível a cada golpe.","Os dispositivos de segurança servem para proteger contra perigos e não devem ser usados ​​em demasia conforme planejado."],"k2-wetterbeobachtung":["O vento aumenta significativamente com uma grande área de carga. O que é necessário?","Uma grande área de componentes funciona como uma vela.","Sempre eleve a carga mais alto para que o vento tenha menos efeito.","Substitua as fundas por outras mais finas.","Avalie os limites operacionais e de vento e ajuste a elevação, se necessário.","O vento pode gerar forças adicionais significativas e movimentos pendulares, especialmente com cargas de grandes áreas."],"k2-ortswechsel":["O que é importante ao mover um guindaste móvel para um novo local?","As condições do subsolo e do suporte mudam.","Verifique a localização e o suporte do suporte antes de pegar novamente a carga.","Aplique as configurações do local anterior sem verificar.","Reajuste o suporte durante o levantamento.","Cada local de instalação pode ter diferentes condições de aterramento e carga de suporte."],"k2-betriebsbereich":["Um guindaste deve funcionar do outro lado da rua. O que precisa ser esclarecido?","Terceiros podem entrar na área de perigo.","Proteja a estrada apenas com uma buzina de alerta.","Bloqueios necessários, medidas de votação e proteção em frente ao hub.","Levante a carga sobre os veículos o mais rápido possível, sem prendê-la.","O roteamento seguro do tráfego evita riscos indevidos a terceiros decorrentes de cargas e movimentos de guindastes."],"k2-hochheben":["Após o levantamento de teste, uma carga fica claramente torta. O que é certo?","O foco foi aparentemente mal avaliado.","Continue levantando para que o desequilíbrio se corrija.","Peça a uma pessoa que puxe a carga inclinada.","Coloque a carga com segurança e verifique novamente o acessório e o centro de gravidade.","O elevador de teste é usado para detectar fixações incorretas e posições de carga instáveis ​​antes do transporte."],"k2-schwebelast":["Você pode deixar uma carga levantada pendurada sem vigilância?","O turno termina, mas a carga ainda está no gancho.","Não, abaixe a carga com segurança e fixe o guindaste adequadamente.","Sim, se a grua estiver bloqueada para não se afastar.","Sim, desde que haja uma placa de alerta no terreno.","Em princípio, as cargas suspensas não devem ser deixadas sem vigilância."],"k2-mitnahme":["Um colega quer andar numa grua. O que se aplica?","A carga deve ser transportada para um ponto mais alto.","É permitido andar de bicicleta desde que o colega use capacete.","As pessoas não podem ser transportadas ou presas a cargas normais.","A carona é sempre permitida desde que o colega seja conhecido do operador do guindaste.","Transportar pessoas junto com cargas cria riscos significativos de queda e esmagamento."],"k2-warnsignal":["Um sistema de alerta operacional no guindaste falha. O que é certo?","Não é mais possível avisar antes de partir.","Ignore o sistema quando o motor estiver funcionando.","Substitua permanentemente o aviso tocando na caixa.","Relate uma falha relacionada à segurança e interrompa as operações de acordo com as instruções.","Os dispositivos de alerta necessários devem estar funcionais para que as pessoas sejam protegidas em tempo hábil."],"k2-schneekante":["Um guindaste móvel precisa ser apoiado em solo congelado e irregular. O que se aplica?","O solo pode perder a sua capacidade de suporte à medida que descongela.","Avalie a capacidade de carga e a situação de suporte em condições reais.","O solo congelado sempre tem alguma capacidade de carga.","Coloque os suportes apenas em pedras pequenas.","A temperatura, a umidade e a estrutura do subsolo influenciam a capacidade de carga dos locais dos guindastes."],"k2-laufkatze":["Um carrinho se move em direção a um obstáculo. Como você age?","Há um objeto na área de condução.","Empurre lentamente o objeto junto com a carga.","Interrompa o movimento a tempo e remova o obstáculo com segurança.","Passe pelo obstáculo em maior velocidade.","Os movimentos do guindaste devem ser orientados de forma que não ocorram colisões com obstáculos."],"k2-anschlagaufnahme":["Você deve pegar uma carga usando um ilhó não designado. O que é certo?","O ilhó só poderia ser destinado à montagem de uma tampa.","Cada ilhó é adequado para carga total do guindaste.","Carregue o ilhó apenas com duas pessoas ao mesmo tempo.","Verifique a capacidade de carga e a adequação do ponto de ancoragem antes de usar.","Nem todos os ilhós existentes são um ponto de fixação estável para cargas de guindaste."],"l2-seilbruch":["Um cabo de aço mostra vários fios individuais quebrados. O que é certo?","Os pontos de ruptura estão na área do cabo de suporte.","Não continue a usar equipamentos de elevação e leve-os para avaliação profissional.","Dobre as pontas do fio para trás com as mãos desprotegidas.","Continue usando a corda se a carga for particularmente leve.","Quebras de fio podem ser critério de descarte; Cordas danificadas devem ser avaliadas profissionalmente."],"l2-schaekel":["O que é crucial ao usar uma manilha?","Uma manilha conecta a eslinga e a carga.","Substitua o parafuso por qualquer prego.","Verifique a capacidade de carga adequada, a condição sem danos e os parafusos corretos.","Estime a capacidade de carga com base na cor.","As manilhas devem ser dimensionadas adequadamente, usadas completamente e na direção de carregamento pretendida."],"l2-tragfaehigkeit":["O que você deve considerar ao usar vários fios?","Os fios formam um ângulo com a vertical.","Basta somar a capacidade de carga de cada fio conforme desejado.","Pendure a carga apenas no fio mais leve.","Considere a capacidade de carga de todo o tipo de âncora e ângulo.","O ângulo de inclinação e o número efetivo de fios influenciam significativamente a carga admissível."],"l2-schweissnaht":["Um ponto de ancoragem improvisado pode ser soldado a uma carga?","Não há pontos de coleta designados adequados para a carga.","Utilize apenas pontos de ancoragem devidamente concebidos e aprovados.","Qualquer costura de solda é suficiente sem teste.","Insira um gancho através de uma abertura na chapa metálica.","Os pontos de ancoragem devem ser comprovados como adequados às forças envolvidas na elevação."],"l2-einseitig":["Uma carga é significativamente mais pesada de um lado. Como você faz isso?","O centro de gravidade está fora do centro geométrico.","Deixe todos os fios com o mesmo comprimento, independentemente do centro de gravidade.","Determine o centro de gravidade e ajuste a posição de acordo.","Primeiro eleve a carga até a altura total de elevação.","Se o centro de gravidade estiver descentralizado, as cargas podem tombar inesperadamente ou os fios individuais podem ficar sobrecarregados."],"l2-kettenriss":["O que se aplica a uma linga de corrente com fissuras visíveis?","Há uma rachadura em um dos elos da corrente.","Marque a rachadura com tinta e levante-a inalterada.","Enrole o link com fio e reutilize-o.","Remova a corrente imediatamente e informe a pessoa responsável.","As fissuras nos elos da corrente de suporte são danos relevantes para a segurança e requerem a desativação."],"l2-lastfuehrung":["Como transportar uma carga grande quando há risco de rotação?","A carga pode oscilar para o lado durante a elevação.","Utilize dispositivos de orientação adequados e mantenha uma distância segura.","Segure a carga diretamente entre as mãos enquanto dirige.","Passe sob a carga e alinhe-a por baixo.","A orientação da carga não deve fazer com que mãos ou corpos entrem na zona de perigo."],"l2-schnueren":["O que é importante ao prender os cadarços?","A eslinga é guiada em torno de um componente.","Assuma a mesma capacidade de carga que qualquer outro tipo de âncora.","Observe a adequação do tipo de fixação e da carga admissível conforme marcação.","Puxe a engrenagem de suspensão em qualquer extensão sem verificar.","O tipo de fixação do cadarço pode alterar a capacidade de carga permitida e deve ser utilizado corretamente."],"l2-winkelmesser":["Por que você não pode ignorar um ângulo de fio plano?","Duas linhas de linga correm quase horizontalmente em relação à carga.","Um ângulo plano torna o fio automaticamente mais forte.","A carga é sempre distribuída igualmente, independentemente do ângulo.","Forças elevadas nos cordões podem exceder a capacidade de carga permitida.","À medida que o ângulo com a vertical aumenta, as tensões nos fios aumentam."],"l2-heisse-last":["O que você precisa verificar para uma carga quente?","Uma peça de aço foi recentemente tratada termicamente.","Observe os limites de temperatura das eslingas e escolha adequada.","Cada funda têxtil pode suportar qualquer temperatura.","A rotulagem não importa quando está quente.","A temperatura pode afetar a capacidade de carga permitida das lingas."],"l2-abstand":["Você consegue colocar os dedos sob a carga ao pousá-la?","A carga deve pousar em uma superfície com precisão milimétrica.","Sim, se você usar luvas de trabalho.","Não, mantenha distância e use meios adequados.","Sim, se o movimento da grua for particularmente lento.","Partes do corpo entre a carga e a base podem ficar presas."],"l2-verbindung":["Um elo de ligação da corrente de linga não está travado. O que se aplica?","O fixador está faltando.","Use o ferrolho sem trava quando ninguém estiver olhando.","Sele o elemento com fita adesiva.","Não bata até que o fixador esteja devidamente preso.","Os elementos de ligação devem ser fixados completamente e de acordo com a sua concepção."],"l2-lasthaken":["O que você verifica ao pendurar no gancho de um guindaste?","Várias eslingas devem ser guiadas para dentro do gancho.","Garanta o ajuste seguro e a adequação dos ganchos e da suspensão.","Coloque as fundas na ponta do gancho.","Substitua a trava do gancho por uma braçadeira.","A força deve ser aplicada conforme pretendido nas áreas designadas."],"l2-fasern":["Uma cinta de elevação apresenta rugosidade severa e danos nas fibras. O que é certo?","As fibras de suporte estão visivelmente danificadas.","Cubra o dano com outro nó.","Separe a cinta de elevação e leve-a a um especialista.","Em seguida, levante a carga mais rapidamente.","Fibras de suporte danificadas podem reduzir significativamente a capacidade de suporte de carga de uma cinta de elevação."],"l2-anheben":["O que se aplica imediatamente após o primeiro centímetro de levantamento?","A carga está apenas saindo de sua base.","Puxe a carga até a altura total sem controle.","Verifique sob a carga se as lingas estão tensionadas.","Verifique a posição da parada, equilíbrio e comportamento do movimento.","Um levantamento de teste controlado torna possíveis instabilidades visíveis antes do transporte posterior."],"l2-lastgewichte":["O peso da carga é desconhecido. O que é certo?","O componente não possui marcação de peso.","Determine o peso carregável antes de selecionar as eslingas.","Estime o peso com base na cor da carga.","Use qualquer tipoia de comprimento duplo.","Sem um peso conhecido ou determinado de forma confiável, a adequação das lingas não pode ser verificada com certeza."],"l2-lose-teile":["Existem ferramentas soltas na carga a ser elevada. O que você está fazendo?","As ferramentas podem cair durante o levantamento.","Segure as ferramentas com uma mão ao dirigir.","Remova ou prenda com eficácia objetos soltos antes de levantá-los.","Levante a carga um pouco mais rápido para que nada escorregue.","Objetos soltos podem cair e colocar em perigo as pessoas na área."],"l2-wind":["Uma grande carga é anexada a ventos fortes. O que se aplica?","O componente oferece ao vento uma grande área de superfície para atacar.","Eleve a carga sem considerar movimentos oscilantes.","Outras pessoas deverão segurar a carga diretamente.","Avalie as condições do vento e evite levantar pesos se a situação for insegura.","As forças do vento podem afetar a orientação e a estabilidade da carga durante o transporte."],"l2-unterlage":["Por que os documentos adequados são importantes durante o desmame?","Uma carga redonda rolaria pelo chão.","Coloque a carga firmemente no chão e proteja-a contra rolamento, se necessário.","Deixe a carga apoiada diretamente nas lingas.","Empurre os documentos sob a carga apenas depois de terem sido colocados.","Suportes adequados evitam tombamento e movimentos indesejados ao pousar."],"l2-transportweg":["O que precisa ser coordenado antes da carga ser transportada?","A carga é movimentada por diversas áreas de trabalho.","Apenas a duração esperada do hub.","Caminho de carga seguro, comunicação e barreiras necessárias.","Uma pessoa deve mostrar o caminho sob a carga.","O transporte de cargas requer rotas de tráfego seguras e uma coordenação clara."],"l2-schutzschlauch":["O que você deve prestar atenção ao usar fundas com mangueira de proteção?","Uma banda encontra-se contra uma borda áspera.","Qualquer pano fino substitui a proteção adequada das bordas.","Uma mangueira protetora elimina qualquer limite de carga permitido.","Selecione o equipamento de proteção de acordo com os requisitos de adequação e aplicação.","Os equipamentos de proteção devem corresponder ao material, à borda e à carga pretendida."],"l2-reinigung":["Uma cinta de elevação estava contaminada com um produto químico desconhecido. O que é certo?","A fita não pode mais ser avaliada com clareza.","Interrompa o uso e esclareça a compatibilidade ou condição profissionalmente.","Limpe com qualquer solvente e continue levantando imediatamente.","Ignore o produto químico enquanto a fita estiver seca.","Os produtos químicos podem afetar a resistência das lingas têxteis."],"l2-aufhaengung":["O que você verifica se há vários fios no elo de suspensão?","Dois fios são colocados juntos em uma suspensão.","Um fio pode mover-se para a ponta do anzol à vontade.","Todos os elementos de ligação devem ser adequados e dispostos conforme pretendido.","Um anel com rachadura pode ser usado para pequenas cargas.","Os elementos de batente e de conexão devem ser resistentes e dispostos corretamente."],"l2-einweiserrolle":["O que se aplica se o atacante e o operador do guindaste não tiverem linha de visão?","Uma transportadora bloqueia a visão do ponto de lançamento.","Coordene ligando para várias pessoas sem responsabilidade.","Mova a carga com base no ruído sem instruções.","Organize uma comunicação clara e segura e interrompa-a se não estiver clara.","A falta de visibilidade deve ser compensada por uma coordenação eficaz e uma comunicação segura."],"l2-ausserbetrieb":["Uma tipoia danificada foi resolvida. O que mais é importante?","Ele permanece acessível gratuitamente juntamente com recursos prontos para uso.","Proteja-se contra uso acidental posterior e informe a pessoa responsável.","Devolva o produto sem marcação ao estoque.","Utilize-o novamente apenas quando transportar uma carga particularmente leve.","As eslingas descartadas devem ser protegidas de forma confiável antes de serem usadas novamente."],"b2-schwenkradius":["Por que o raio de giro traseiro de uma escavadeira é crítico?","A cauda se move sobre uma área de trabalho limitada.","Terceiros podem ser apanhados pela superestrutura oscilante.","O raio de giro não influencia as pessoas próximas à máquina.","A traseira sempre se move apenas na direção de deslocamento.","Ao girar, surge também uma área de perigo atrás da máquina."],"b2-verkehrseinweiser":["Como é assegurado um movimento de condução quando a visibilidade está obscurecida?","Uma escavadeira precisa manobrar atrás de um obstáculo.","Dirija sem ver os sinais do sinalizador.","Se necessário, organize instruções apropriadas com comunicação clara.","Proteja a marcha-atrás apenas buzinando uma vez.","Rotas confusas exigem medidas eficazes para evitar colisões e aprisionamentos."],"b2-standplatz":["O que se aplica a uma escavadeira em um declive?","O piso é inclinado e pode estar escorregadio.","A máquina pode estender-se tanto quanto quiser em qualquer inclinação.","Sempre instale a escavadeira sobre uma camada solta de terra.","Verifique a estabilidade e os limites operacionais da máquina antes de usá-la.","A encosta e o subsolo têm uma influência significativa na estabilidade."],"b2-oberleitung":["Porque é que a distância da barragem às linhas eléctricas precisa de ser planeada?","A lança pode aproximar-se do cabo ao girar.","A descarga elétrica também é possível sem contato direto.","Somente a caçamba pode conduzir eletricidade, não a lança.","Com solo seco, todas as distâncias são automaticamente seguras.","Os limites de utilização e as distâncias de proteção devem ser esclarecidos antes de se aproximar dos sistemas elétricos."],"b2-fremdperson":["Um transeunte entra no canteiro de obras na área panorâmica. O que é certo?","A pessoa de repente fica perto da caçamba da escavadeira.","Levante a pá e balance-a sobre a pessoa.","Pare o movimento imediatamente e limpe a área.","Continue observando a pessoa pela janela lateral.","As pessoas na área de perigo não devem ser colocadas em perigo devido aos movimentos de trabalho."],"b2-parkstellung":["Como é feita a segurança de uma máquina de terraplenagem após o término do trabalho?","A escavadeira permanece autônoma no canteiro de obras.","Deixe a colher na altura da cabeça.","Deixe o motor funcionar sem supervisão.","Abaixe o equipamento de trabalho, proteja a máquina e evite o uso não autorizado.","O estacionamento adequado reduz o movimento acidental e o acesso não autorizado."],"b2-eigenlast":["Por que os limites do equipamento são cruciais ao levantar com uma escavadeira?","Uma carga pesada deve ser recolhida na lança.","Caso contrário, a estabilidade e a capacidade de carga permitida poderão ser excedidas.","Qualquer máquina pode levantar qualquer carga, desde que a caçamba caiba.","Apenas o comprimento da corda de içamento determina o risco.","As informações de elevação e capacidade de carga dependem do equipamento e da situação da aplicação."],"b2-untergrundhohlraum":["O piso acima de um porão antigo pode ser oco. O que você está fazendo?","Você deve dirigir a escavadeira para a área.","Cruze o local com impulso máximo.","Esclareça a capacidade de carga e possíveis cavidades antes de prosseguir.","Basta colocar uma carga pesada na superfície.","As cavidades podem colapsar sob o peso da máquina e causar a queda da máquina."],"b2-feuchtigkeit":["Depois de fortes chuvas, o aterro fica mole. O que é certo?","Uma escavadeira trabalha perto da borda do aterro.","Aproxime a máquina da borda para aumentar o alcance.","Ignore as mudanças até o final do turno.","Reavaliar as condições do solo e de estabilidade.","A penetração de umidade pode alterar a capacidade de carga e a estabilidade dos aterros."],"b2-bodenprobe":["Por que os planos dos gasodutos devem ser verificados antes da escavação?","Os cabos poderiam passar sob a escavação planejada.","Para que as linhas possam ser identificadas e possam ser planeadas medidas de segurança adequadas.","Para que a escavação possa ser realizada de forma mais rápida, independentemente de sistemas de terceiros.","Porque as máquinas nunca devem ser utilizadas perto de cabos.","As linhas de abastecimento subterrâneas requerem esclarecimento confiável da localização antes dos trabalhos de escavação."],"b2-maschinenzugang":["O que se aplica ao entrar e sair da máquina de terraplenagem?","A máquina está em terreno irregular.","Deslize a linha hidráulica para fora da cabine.","Use etapas designadas e garanta uma base segura.","Salte para o braço giratório enquanto a máquina estiver funcionando.","Subidas seguras e pontos de parada adequados reduzem o risco de queda e esmagamento."],"b2-kupplung":["Como você verifica uma nova retroescavadeira após a instalação?","A caçamba é conectada através do acoplador rápido.","Julgue a colher apenas visualmente de uma distância maior.","Passe diretamente sob a colher levantada.","Garanta o travamento correto e as etapas de controle prescritas.","Acessórios bloqueados incorretamente podem se soltar e colocar pessoas em perigo."],"b2-hydraulikwartung":["Por que as linhas hidráulicas não podem ser abertas sob pressão?","Uma mangueira precisa ser substituída.","O vazamento de fluido pode causar ferimentos graves devido à alta pressão.","A pressão sempre impede que o óleo escape.","Uma linha aberta pode ser verificada com segurança com as mãos.","O fluido de alta pressão pode penetrar no tecido e requer um alívio de pressão seguro."],"b2-fahrweg":["Você tem que passar por uma ponte de construção temporária. O que você está verificando?","A ponte foi projetada apenas para determinadas cargas.","Se a cor da ponte combina com a máquina.","Capacidade de carga e adequação ao peso e dimensões da máquina.","Somente se um carro leve já passou pela ponte.","As estruturas temporárias só podem ser utilizadas dentro da sua capacidade de carga comprovada."],"b2-baggertransport":["O que é importante ao transportar uma escavadeira em uma carregadeira baixa?","A máquina é levada para o próximo canteiro de obras.","Deixe o equipamento de trabalho sobressair livremente da borda.","Mantenha a porta da cabine aberta enquanto dirige.","Fixe a máquina de acordo com as especificações de transporte e verifique o equipamento de carregamento.","Bloqueios de transporte e instalações de carregamento adequadas evitam escorregões e quedas."],"b2-schaufelfuellung":["Por que uma carregadeira de rodas não pode andar rápido com a caçamba elevada?","A carga é pesada e o terreno é irregular.","Um centro de gravidade elevado pode aumentar o risco de tombamento e problemas de visibilidade.","A caçamba estabiliza automaticamente em altas velocidades.","A altura da pá é irrelevante para a estabilidade.","Um centro de gravidade elevado normalmente piora a estabilidade ao dirigir e fazer curvas."],"b2-fussgaenger":["Como você se comporta ao manobrar próximo a pedestres?","O acesso ao canteiro de obras também é feito por uma trilha.","Use a pá para direcionar os pedestres para o lado.","Execute o movimento de condução apenas quando a área estiver segura e controlável.","Basta buzinar uma vez e dirigir lentamente, sem visibilidade.","O tráfego de veículos e passageiros deve ser efetivamente separado ou coordenado de forma segura."],"b2-ueberlastwarnung":["Ao levantar, a máquina reporta sobrecarga. O que você está fazendo?","Uma carga elevada atinge os limites permitidos.","Desligue o aviso e continue a aumentá-lo inalterado.","Aperte a carga repentinamente enquanto a máquina estiver funcionando.","Pare movimentos perigosos e corrija com segurança a situação da carga.","Os avisos de sobrecarga indicam possíveis violações de limites e riscos de estabilidade."],"b2-wasserleitung":["Durante a escavação, um cano desconhecido é descoberto. O que se aplica?","A linha não consta dos planos de construção.","Pare de trabalhar na área afetada e identifique a linha profissionalmente.","Tente mover a linha com a pá da escavadeira.","Continue cavando diretamente abaixo da linha sem verificar.","Linhas desconhecidas podem causar riscos elétricos, de gás ou de água."],"b2-hangefahrt":["Como você dirige uma escavadeira em uma encosta íngreme?","O percurso planeado segue ao longo de uma encosta.","Atravesse a encosta independentemente dos limites do fabricante.","Observe a inclinação permitida e o estilo de condução prescrito da máquina.","Balance a lança bem para fora para equilibrar o veículo.","A inclinação permitida depende da máquina, da superfície e das informações do fabricante."],"b2-schlechtebeleuchtung":["Ao trabalhar num poço escuro, a visibilidade é inadequada. O que é certo?","Você dificilmente consegue ver pessoas e obstáculos.","Aumente a velocidade de escavação para concluir a operação rapidamente.","Não use as luzes enquanto o motor estiver funcionando.","Pare o trabalho até que as áreas de perigo estejam suficientemente visíveis.","A visibilidade segura das áreas de condução e de trabalho é necessária para movimentos controlados da máquina."],"b2-kettenverschleiss":["Durante a verificação diária, é notada uma trilha de lagarta danificada. O que você está fazendo?","Uma conexão em cadeia mostra danos claros.","Não continue a utilizar a máquina de forma descontrolada e comunique quaisquer danos.","Continue dirigindo em alta velocidade para que a corrente fique reta.","Continue trabalhando apenas em solo macio sem verificar.","Danos ao inversor podem prejudicar o controle e a estabilidade."],"b2-ladearbeiten":["Você carrega um caminhão com a escavadeira. O que é importante?","O motorista do caminhão permanece próximo à área de carga.","Balance a caçamba sobre a cabine do motorista desprotegida.","Impedir que as pessoas permaneçam na área de perigo e coordenar os processos.","Comece a carregar sem se comunicar com o driver.","Durante o carregamento existe o risco de queda de material e movimentos oscilantes."],"b2-arbeitsunterbrechung":["Você interrompe o trabalho de escavação para uma reunião. O que se aplica?","A máquina deve ficar parada por vários minutos sem ser operada.","Deixe a pá levantada como marcador.","Deixe a máquina sem vigilância com a transmissão de tração engatada.","Coloque o implemento de forma segura e proteja a máquina contra uso involuntário.","Mesmo pequenas interrupções exigem condições seguras da máquina."],"b2-rollmaterial":["Material solto pode cair durante o transporte com a carregadeira de rodas. O que é certo?","A carregadeira se aproxima dos funcionários.","Pegue a carga com segurança e escolha um estilo de condução seguro com uma posição adequada da escavadeira.","Levante a pá o mais alto possível para que a área circundante tenha uma visão clara.","Pegue a carga sem limitar o enchimento da caçamba.","Cargas soltas, posições altas da caçamba e pouca visibilidade podem colocar pessoas e tráfego em perigo."]};
